// SUPER SIX signal desk - single-file version for easy upload (phone friendly).
// On start it unpacks the desk into ./app and runs it. Nothing to install.
const fs = require('fs'), path = require('path');
const FILES = {"server.js": "const http = require('http');\nconst fs = require('fs');\nconst path = require('path');\nconst { ASSETS, getCandles, withTimeout } = require('./lib/data');\nconst { runSuperSix, overlays, applyLive } = require('./lib/agents');\nconst Live = require('./lib/live');\nconst { TF_MS } = require('./lib/data');\nconst News = require('./lib/news');\n\nconst PORT = process.env.PORT || 3000;\nconst SERVER_STARTED = Date.now();\nconst DATA_DIR = path.join(__dirname, 'data');\nconst SIG_FILE = path.join(DATA_DIR, 'signals.json');\nconst SET_FILE = path.join(DATA_DIR, 'settings.json');\nfs.mkdirSync(DATA_DIR, { recursive: true });\n\nconst load = (f, d) => { try { return JSON.parse(fs.readFileSync(f, 'utf8')); } catch { return d; } };\nlet settings = { account: 10000, riskPct: 1, minRR: 2, minConf: 70, ...load(SET_FILE, {}) };\nlet signals = load(SIG_FILE, []);\nconst results = {};\nconst errors = {};\nlet news = { items: [], entities: {}, calendar: [] };\nlet lastScan = 0, scanning = false, scanCount = 0;\nlet activity = [];   // what changed on each scan\n\nasync function refreshNews() {\n  const [h, c] = await Promise.allSettled([News.getHeadlines(), News.getCalendar()]);\n  if (h.status === 'fulfilled') { news.items = h.value.items; news.entities = News.entityScores(h.value.items); news.sources = `${h.value.sources}/${h.value.total}`; }\n  if (c.status === 'fulfilled') { news.calendar = c.value; news.calendarError = false; } else news.calendarError = !news.calendar.length;\n}\n\nasync function pool(items, n, fn) {\n  const q = [...items];\n  await Promise.all(Array.from({ length: n }, async () => { while (q.length) await fn(q.shift()); }));\n}\n\nfunction trackOutcomes() {\n  for (const s of signals) {\n    if (s.outcome !== 'OPEN') continue;\n    const r = results[s.sym];\n    if (!r) continue;\n    const cs = r.T.m15.candles.filter(c => c.t > s.t);\n    for (const c of cs) {\n      const up = s.dir === 'BUY';\n      const hitSL = up ? c.l <= s.sl : c.h >= s.sl;\n      const hitTP1 = up ? c.h >= s.tp1 : c.l <= s.tp1;\n      const hitTP2 = s.tp2 != null && (up ? c.h >= s.tp2 : c.l <= s.tp2);\n      if (hitSL) { s.outcome = s.tp1Hit ? 'BE/PARTIAL' : 'LOSS'; s.closedAt = c.t; break; }\n      if (hitTP1) s.tp1Hit = true;\n      if (hitTP2) { s.outcome = 'WIN'; s.closedAt = c.t; break; }\n    }\n    if (s.outcome === 'OPEN' && Date.now() - s.t > 48 * 3600e3) s.outcome = s.tp1Hit ? 'BE/PARTIAL' : 'EXPIRED';\n  }\n}\n\nfunction recordSignal(r) {\n  if (r.status !== 'BUY' && r.status !== 'SELL') return;\n  const dup = signals.find(s => s.sym === r.sym && s.dir === r.status && (s.outcome === 'OPEN' || Date.now() - s.t < 4 * 3600e3));\n  if (dup) return;\n  const p = r.plan;\n  signals.unshift({ id: Date.now() + r.sym, sym: r.sym, cls: r.cls, dp: r.dp, dir: r.status, t: Date.now(), entry: p.entry, sl: p.sl, tp1: p.tp1, tp2: p.tp2, rr: p.rr, confidence: r.confidence, outcome: 'OPEN' });\n  signals = signals.slice(0, 300);\n}\n\nlet scanStarted = 0;\nasync function scan(force = false) {\n  if (scanning && Date.now() - scanStarted < 120e3) return;\n  if (!force && Date.now() - scanStarted < 28e3) return;\n  scanStarted = Date.now();\n  scanning = true;\n  try {\n    await withTimeout(refreshNews(), 30000, 'news').catch(e => console.error('news', e.message));\n    const prices = {};\n    Object.values(results).forEach(r => { prices[r.sym] = r.price; });\n    await pool(ASSETS, 5, async asset => {\n      try {\n        const raw = {};\n        for (const tf of ['15m', '1h', '4h']) raw[tf] = await withTimeout(getCandles(asset, tf), 30000, asset.sym + ' ' + tf);\n        const prev = results[asset.sym];\n        const next = runSuperSix(asset, raw, news, settings, { prices, live: Live.get(asset.sym, 20e3) });\n        if (prev) {\n          const changes = [];\n          if (prev.status !== next.status) changes.push(`${prev.status} → ${next.status}`);\n          else if (prev.passCount !== next.passCount) changes.push(`${prev.passCount}/6 → ${next.passCount}/6`);\n          next.agents.forEach((ag, i) => { const pa = prev.agents[i]; if (pa && pa.pass !== ag.pass) changes.push(`${ag.name.replace(' Agent', '')} ${ag.pass ? 'PASS ✓' : 'FAIL ✗'}`); });\n          if (prev.dir !== next.dir) changes.push(`bias ${prev.dir === 1 ? 'BUY' : prev.dir === -1 ? 'SELL' : 'none'} → ${next.dir === 1 ? 'BUY' : next.dir === -1 ? 'SELL' : 'none'}`);\n          if (changes.length) activity.unshift({ t: Date.now(), sym: asset.sym, dp: asset.dp, status: next.status, pass: next.passCount, text: changes.join(' · '), price: next.price });\n        }\n        results[asset.sym] = next;\n        delete errors[asset.sym];\n        recordSignal(results[asset.sym]);\n      } catch (e) { errors[asset.sym] = String(e.message || e); console.error(asset.sym, e.message); }\n    });\n    activity = activity.slice(0, 80);\n    trackOutcomes();\n    fs.writeFileSync(SIG_FILE, JSON.stringify(signals, null, 1));\n    writeSnapshot();\n    lastScan = Date.now(); scanCount++;\n    if (Date.now() - scanStarted > 60e3) console.warn('slow scan', Date.now() - scanStarted, 'ms');\n    console.log(`[scan ${scanCount}] ${new Date().toISOString()} (${((Date.now() - scanStarted) / 1000).toFixed(1)}s) — ${Object.keys(results).length} assets, ${Object.values(results).filter(r => r.status === 'BUY' || r.status === 'SELL').length} live signals`);\n  } catch (e) { console.error('scan error', e); } finally { scanning = false; }\n}\n\nfunction livePrice(r) {\n  const lp = Live.get(r.sym, 60e3);\n  if (!lp) return { price: r.price, change24: r.change24, priceT: r.priceT, priceSrc: r.priceSrc };\n  return { price: lp.price, change24: r.ref24 ? (lp.price - r.ref24) / r.ref24 * 100 : r.change24, priceT: lp.t, priceAt: lp.at, priceSrc: lp.src };\n}\nconst ASSET_BY = Object.fromEntries(ASSETS.map(a => [a.sym, a]));\nfunction summary(r) {\n  const A = ASSET_BY[r.sym] || {};\n  return {\n    sym: r.sym, name: r.name, cls: r.cls, dp: r.dp, src: A.src, id: A.id, tv: A.tv, delay: A.delay || 0, ...livePrice(r), ref24: r.ref24, dir: r.dir, status: r.status,\n    passCount: r.passCount, confidence: r.confidence, trends: r.trends,\n    agents: r.agents.map(a => ({ id: a.id, pass: a.pass, score: a.score })), updatedAt: r.updatedAt,\n  };\n}\n\nfunction stats() {\n  const closed = signals.filter(s => s.outcome !== 'OPEN' && s.outcome !== 'EXPIRED');\n  const wins = closed.filter(s => s.outcome === 'WIN').length;\n  return { total: signals.length, open: signals.filter(s => s.outcome === 'OPEN').length, wins, losses: closed.filter(s => s.outcome === 'LOSS').length, winRate: closed.length ? Math.round(wins / closed.length * 100) : null };\n}\n\nfunction stripAgent(a) {\n  const { headlines, ...rest } = a;\n  return { ...rest, headlines: headlines ? headlines.map(h => ({ title: h.title, link: h.link, t: h.t, source: h.source, pol: h.pol })) : undefined };\n}\n\nfunction deskPayload() {\n  const now = Date.now();\n  return {\n    lastScan, scanning, settings, stats: stats(), errors,\n    assets: ASSETS.map(a => results[a.sym] ? summary(results[a.sym]) : { sym: a.sym, name: a.name, cls: a.cls, dp: a.dp, tv: a.tv, src: a.src, id: a.id, delay: a.delay || 0, pending: true, error: errors[a.sym] }),\n    signals: signals.slice(0, 60),\n    calendar: news.calendar.filter(e => (e.impact === 'High' || e.impact === 'Medium') && e.t > now - 2 * 3600e3).sort((a, b) => a.t - b.t).slice(0, 25),\n    headlines: news.items.filter(h => h.ents.length).slice(0, 40).map(h => ({ title: h.title, link: h.link, t: h.t, source: h.source, pol: h.pol, ents: h.ents })),\n    newsSources: news.sources, entities: news.entities, liveStatus: Live.status, now: Date.now(),\n    activity: activity.slice(0, 40), scanCount, serverStarted: SERVER_STARTED,\n  };\n}\nfunction detailPayload(r) {\n  const lp = Live.get(r.sym, 60e3);\n  if (lp) for (const tf of ['15m', '1h', '4h']) applyLive(r.T[tf === '15m' ? 'm15' : tf === '1h' ? 'h1' : 'h4'].candles, TF_MS[tf], lp);\n  return {\n    ...summary(r), plan: r.plan, daily: r.daily, agents: r.agents.map(stripAgent),\n    charts: { '15m': overlays(r.T.m15), '1h': overlays(r.T.h1), '4h': overlays(r.T.h4) },\n  };\n}\nconst SNAP_FILE = path.join(__dirname, '..', 'SuperSix_Desk.html');\nconst SNAP_ON = process.env.SNAPSHOT ? process.env.SNAPSHOT === '1' : !process.env.RENDER && !process.env.NO_SNAPSHOT;\nfunction writeSnapshot() {\n  if (!SNAP_ON) return;\n  try {\n    const snap = { desk: { ...deskPayload(), scanning: false, lastScan: Date.now() }, assets: {} };\n    for (const r of Object.values(results)) snap.assets[r.sym] = detailPayload(r);\n    const html = fs.readFileSync(path.join(__dirname, 'public', 'index.html'), 'utf8')\n      .replace('<script>', '<script>window.__SNAPSHOT__=' + JSON.stringify(snap).replace(/</g, '\\\\u003c') + ';</script>\\n<script>');\n    fs.writeFileSync(SNAP_FILE + '.tmp', html);\n    fs.renameSync(SNAP_FILE + '.tmp', SNAP_FILE);\n  } catch (e) { console.error('snapshot', e.message); }\n}\n\nconst send = (res, code, body, type = 'application/json') => {\n  res.writeHead(code, { 'Content-Type': type, 'Cache-Control': 'no-store' });\n  res.end(typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body));\n};\n\nconst MIME = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml' };\n\nhttp.createServer(async (req, res) => {\n  const url = new URL(req.url, 'http://x');\n  try {\n    if (url.pathname === '/api/health') return send(res, 200, { ok: true, scanCount, lastScan, uptime: Math.round(process.uptime()) });\n    if (url.pathname === '/api/desk') { scan().catch(() => {}); return send(res, 200, deskPayload()); }\n    if (url.pathname === '/api/asset') {\n      const r = results[url.searchParams.get('sym')];\n      if (!r) return send(res, 404, { error: 'not ready' });\n      return send(res, 200, detailPayload(r));\n    }\n    if (url.pathname === '/api/prices') {\n      const out = {};\n      for (const [k, v] of Object.entries(Live.prices)) out[k] = { price: v.price, t: v.t, at: v.at, src: v.src };\n      return send(res, 200, { now: Date.now(), prices: out, status: Live.status });\n    }\n    if (url.pathname === '/api/scan' && req.method === 'POST') { await scan(true); return send(res, 200, { ok: true, lastScan }); }\n    if (url.pathname === '/api/settings' && req.method === 'POST') {\n      let body = '';\n      for await (const ch of req) body += ch;\n      const s = JSON.parse(body || '{}');\n      for (const k of ['account', 'riskPct', 'minRR', 'minConf']) if (s[k] != null && !isNaN(+s[k])) settings[k] = +s[k];\n      settings.riskPct = Math.min(5, Math.max(0.1, settings.riskPct));\n      settings.minRR = Math.min(10, Math.max(1, settings.minRR));\n      settings.minConf = Math.min(100, Math.max(0, settings.minConf));\n      fs.writeFileSync(SET_FILE, JSON.stringify(settings));\n      scan(true).catch(() => {});\n      return send(res, 200, settings);\n    }\n    let p = url.pathname === '/' ? '/index.html' : url.pathname;\n    const file = path.join(__dirname, 'public', path.normalize(p).replace(/^(\\.\\.[/\\\\])+/, ''));\n    if (file.startsWith(path.join(__dirname, 'public')) && fs.existsSync(file) && fs.statSync(file).isFile())\n      return send(res, 200, fs.readFileSync(file), MIME[path.extname(file)] || 'application/octet-stream');\n    send(res, 404, 'Not found', 'text/plain');\n  } catch (e) { console.error(e); send(res, 500, { error: e.message }); }\n}).listen(PORT, '0.0.0.0', () => {\n  const pub = process.env.RENDER_EXTERNAL_URL || process.env.PUBLIC_URL;\n  if (pub) { // free hosts sleep after ~15 min without visitors: ping ourselves through the public URL every 10 min\n    setInterval(() => fetch(pub.replace(/\\/$/, '') + '/api/health').then(r => console.log('[keep-alive]', r.status)).catch(e => console.log('[keep-alive] failed', e.message)), 10 * 60e3);\n    console.log('keep-alive ON via', pub);\n  }\n  console.log(`SUPER SIX desk on http://0.0.0.0:${PORT}`);\n  Live.start();\n  setTimeout(() => scan(true), 2500);\n  setInterval(() => scan().catch(e => console.error(e)), 10e3);\n  process.on('unhandledRejection', e => console.error('unhandled', e && e.message));\n  process.on('uncaughtException', e => console.error('uncaught', e && e.message));\n});\n", "lib/agents.js": "// THE SUPER SIX — every agent must PASS in the same direction, and the Risk agent holds a veto.\nconst S = require('./smc');\nconst N = require('./news');\nconst { TF_MS } = require('./data');\n\nconst SWING = { '15m': 5, '1h': 4, '4h': 3 };\n\nfunction analyzeTF(candles, tf) {\n  const closed = candles.filter(c => c.closed);\n  const live = candles[candles.length - 1];\n  const atrArr = S.atr(closed, 14);\n  const sw = S.swings(closed, SWING[tf]);\n  const st = S.structure(closed, sw);\n  const fv = S.fvgs(closed, atrArr);\n  const ob = S.orderBlocks(closed, st.events, atrArr);\n  const a = atrArr[atrArr.length - 1];\n  const lq = S.liquidity(closed, sw, a);\n  const dr = S.dealingRange(closed, st);\n  return { tf, candles, closed, live, n: closed.length, atr: a, atrArr, sw, st, fv, ob, lq, dr, trend: st.trend };\n}\n\nconst dirWord = d => (d === 1 ? 'BUY' : d === -1 ? 'SELL' : '—');\nconst trendWord = d => (d === 1 ? 'Bullish' : d === -1 ? 'Bearish' : 'Ranging');\n\nfunction finish(agent) {\n  const tot = agent.checks.reduce((s, c) => s + c.w, 0) || 1;\n  agent.score = Math.round(100 * agent.checks.reduce((s, c) => s + (c.ok ? c.w : 0), 0) / tot);\n  agent.pass = agent.checks.filter(c => c.req).every(c => c.ok);\n  agent.status = agent.pass ? 'PASS' : 'FAIL';\n  return agent;\n}\n\n// 1 ── STRUCTURE: multi-timeframe BOS / CHoCH alignment (4H bias → 1H confirm → 15m trigger)\nfunction structureAgent(T) {\n  const { h4, h1, m15 } = T;\n  const D = h4.trend !== 0 ? h4.trend : 0;\n  const ev15 = m15.st.last, ev1 = h1.st.last, ev4 = h4.st.last;\n  const recent15 = ev15 && m15.n - 1 - ev15.i <= 48;\n  const ag = { id: 'structure', name: 'Structure Agent', tag: 'BOS · CHoCH', dir: D, checks: [] };\n  ag.checks.push({ label: '4H bias defined', ok: D !== 0, req: true, w: 30, detail: ev4 ? `${trendWord(h4.trend)} — last 4H ${ev4.type} @ ${fmt(ev4.level)} (streak ${h4.st.streak})` : 'No 4H structure break yet' });\n  ag.checks.push({ label: '1H aligned with 4H', ok: D !== 0 && h1.trend === D, req: true, w: 25, detail: ev1 ? `1H ${trendWord(h1.trend)} — last ${ev1.type} @ ${fmt(ev1.level)}` : 'No 1H break' });\n  ag.checks.push({ label: '15m trigger in bias direction', ok: D !== 0 && m15.trend === D, req: true, w: 25, detail: ev15 ? `15m ${trendWord(m15.trend)} — last ${ev15.type} @ ${fmt(ev15.level)}` : 'No 15m break' });\n  ag.checks.push({ label: '15m break is fresh (≤ 12h)', ok: !!recent15 && m15.trend === D, req: true, w: 15, detail: ev15 ? `${m15.n - 1 - ev15.i} candles ago` : '—' });\n  ag.checks.push({ label: '15m CHoCH → BOS continuation', ok: !!ev15 && ev15.type === 'BOS' && m15.trend === D, req: false, w: 5, detail: ev15 ? `latest is ${ev15.type}` : '—' });\n  ag.summary = D ? `${trendWord(D)} 4H order flow; 1H ${trendWord(h1.trend).toLowerCase()}, 15m ${trendWord(m15.trend).toLowerCase()}.` : '4H is ranging — no directional bias.';\n  return finish(ag);\n}\n\n// 2 ── LIQUIDITY: inducement swept against us, opposing liquidity left as target\nfunction liquidityAgent(T, D, price, daily) {\n  const { h4, h1, m15 } = T;\n  const ag = { id: 'liquidity', name: 'Liquidity Agent', tag: 'BSL · SSL · Sweeps', dir: D, checks: [] };\n  const want = D;\n  const sw15 = m15.lq.sweeps.filter(s => s.dir === want && s.at >= m15.n - 32).pop();\n  const sw1 = h1.lq.sweeps.filter(s => s.dir === want && s.at >= h1.n - 16).pop();\n  const sweep = sw1 ? { ...sw1, tf: '1H' } : sw15 ? { ...sw15, tf: '15m' } : null;\n  const minGap = 0.3 * m15.atr;\n  let targets = [];\n  const push = (p, label) => { if (D === 1 ? p > price + minGap : p < price - minGap) targets.push({ price: p, label }); };\n  if (D === 1) {\n    h1.lq.bsl.forEach(l => push(l.price, l.count > 1 ? '1H EQH' : '1H BSL'));\n    h4.lq.bsl.forEach(l => push(l.price, l.count > 1 ? '4H EQH' : '4H BSL'));\n    if (daily) push(daily.pdh, 'PDH');\n  } else if (D === -1) {\n    h1.lq.ssl.forEach(l => push(l.price, l.count > 1 ? '1H EQL' : '1H SSL'));\n    h4.lq.ssl.forEach(l => push(l.price, l.count > 1 ? '4H EQL' : '4H SSL'));\n    if (daily) push(daily.pdl, 'PDL');\n  }\n  targets.sort((a, b) => Math.abs(a.price - price) - Math.abs(b.price - price));\n  targets = targets.filter((t, i, arr) => i === 0 || Math.abs(t.price - arr[i - 1].price) > 0.2 * m15.atr).slice(0, 5);\n  const seqOK = sweep && m15.st.last && m15.st.last.dir === D && (sweep.tf === '1H' || m15.st.last.i >= sweep.at);\n  const sideTxt = D === 1 ? 'Sell-side (SSL)' : 'Buy-side (BSL)';\n  ag.checks.push({ label: `${sideTxt} liquidity swept`, ok: !!sweep && D !== 0, req: true, w: 40, detail: sweep ? `${sweep.tf} sweep of ${fmt(sweep.price)} (wick ${fmt(sweep.wick)})` : 'No recent stop-hunt in our favour' });\n  ag.checks.push({ label: `Opposing liquidity target ${D === 1 ? 'above' : 'below'}`, ok: targets.length > 0, req: true, w: 35, detail: targets.length ? targets.slice(0, 3).map(t => `${t.label} ${fmt(t.price)}`).join(' · ') : 'No resting liquidity to draw price' });\n  ag.checks.push({ label: 'Sweep → shift in structure sequence', ok: !!seqOK, req: false, w: 15, detail: seqOK ? 'Sweep preceded 15m break' : 'Sequence not confirmed' });\n  const eq = targets.find(t => /EQ/.test(t.label));\n  ag.checks.push({ label: 'Equal highs/lows magnet', ok: !!eq, req: false, w: 10, detail: eq ? `${eq.label} ${fmt(eq.price)}` : 'None nearby' });\n  ag.summary = sweep ? `${sideTxt} taken on ${sweep.tf}; draw on liquidity ${targets[0] ? 'towards ' + fmt(targets[0].price) : 'unclear'}.` : 'Waiting for a liquidity grab before entry.';\n  ag.sweep = sweep; ag.targets = targets;\n  return finish(ag);\n}\n\nfunction tapped(z, tfA, D, lookback) {\n  const live = tfA.live;\n  if (D === 1 && live.l <= z.top && live.h >= z.bottom) return true;\n  if (D === -1 && live.h >= z.bottom && live.l <= z.top) return true;\n  return z.lastTap != null && z.lastTap >= tfA.n - lookback;\n}\n\nfunction inReach(z, price, a, D) {\n  const inside = price >= z.bottom && price <= z.top;\n  const near = D === 1 ? price > z.top && price - z.top <= 0.6 * a : price < z.bottom && z.bottom - price <= 0.6 * a;\n  return { inside, near };\n}\n\n// 3 ── IMBALANCE: price reacting from FVG / inverted FVG; no opposing imbalance in the way\nfunction imbalanceAgent(T, D, price) {\n  const { h1, m15 } = T;\n  const ag = { id: 'imbalance', name: 'Imbalance Agent', tag: 'FVG · iFVG', dir: D, checks: [] };\n  const cands = [];\n  for (const tfA of [h1, m15]) {\n    for (const z of tfA.fv) {\n      if (z.eff !== D) continue;\n      const r = inReach(z, price, tfA.atr, D);\n      if (r.inside || (r.near && tapped(z, tfA, D, 12))) cands.push({ ...z, tf: tfA.tf === '1h' ? '1H' : '15m', inside: r.inside });\n    }\n  }\n  cands.sort((a, b) => (a.tf === '1H' ? 0 : 1) - (b.tf === '1H' ? 0 : 1) || b.i - a.i);\n  const zone = cands[0] || null;\n  const block = h1.fv.find(z => z.eff === -D && (\n    (price >= z.bottom && price <= z.top) ||\n    (D === 1 ? z.bottom > price && z.bottom - price < 0.8 * h1.atr : z.top < price && price - z.top < 0.8 * h1.atr)));\n  ag.checks.push({ label: `Price in/reacting from ${D === 1 ? 'bullish' : 'bearish'} FVG or iFVG`, ok: !!zone && D !== 0, req: true, w: 50, detail: zone ? `${zone.tf} ${zone.kind} ${fmt(zone.bottom)} – ${fmt(zone.top)}${zone.inside ? ' (inside)' : ' (tapped & holding)'}` : 'No imbalance at current price' });\n  ag.checks.push({ label: 'No opposing 1H imbalance blocking path', ok: !block && D !== 0, req: true, w: 30, detail: block ? `Opposing 1H ${block.kind} ${fmt(block.bottom)} – ${fmt(block.top)}` : 'Clear path' });\n  ag.checks.push({ label: 'Confluence: iFVG or stacked gaps', ok: cands.some(c => c.kind === 'iFVG') || cands.length >= 2, req: false, w: 20, detail: `${cands.length} supporting zone(s)${cands.some(c => c.kind === 'iFVG') ? ', iFVG present' : ''}` });\n  ag.summary = zone ? `${zone.tf} ${zone.kind} supports the ${dirWord(D)} idea.` : 'No fair value gap supporting entry right now.';\n  ag.zone = zone;\n  return finish(ag);\n}\n\n// 4 ── ORDER FLOW: fresh order block at price + premium/discount location\nfunction orderBlockAgent(T, D, price) {\n  const { h4, h1, m15 } = T;\n  const ag = { id: 'orderblock', name: 'Order Block Agent', tag: 'OB · Premium/Discount', dir: D, checks: [] };\n  const cands = [];\n  for (const tfA of [h4, h1, m15]) {\n    for (const z of tfA.ob) {\n      if (z.dir !== D || z.state === 'broken' || z.touches > 2) continue;\n      const r = inReach(z, price, tfA.atr, D);\n      if (r.inside || (r.near && tapped(z, tfA, D, 12))) cands.push({ ...z, tf: tfA.tf.toUpperCase().replace('M', 'm'), inside: r.inside });\n    }\n  }\n  const rank = { '4H': 0, '1H': 1, '15m': 2 };\n  cands.sort((a, b) => rank[a.tf] - rank[b.tf] || b.bosAt - a.bosAt);\n  const ob = cands[0] || null;\n  const dr = h1.dr;\n  const pos = dr ? (price - dr.lo) / ((dr.hi - dr.lo) || 1) : 0.5;\n  const pdOK = dr && (D === 1 ? pos < 0.5 : D === -1 ? pos > 0.5 : false);\n  ag.checks.push({ label: `Price at ${D === 1 ? 'bullish' : 'bearish'} order block`, ok: !!ob && D !== 0, req: true, w: 45, detail: ob ? `${ob.tf} OB ${fmt(ob.bottom)} – ${fmt(ob.top)} (${ob.bosType}, ${ob.touches === 0 ? 'fresh' : ob.touches + ' tap'})` : 'No valid order block at price' });\n  ag.checks.push({ label: `In ${D === 1 ? 'discount' : 'premium'} of 1H dealing range`, ok: !!pdOK, req: true, w: 30, detail: dr ? `Range ${fmt(dr.lo)} – ${fmt(dr.hi)}, price at ${(pos * 100).toFixed(0)}% (EQ ${fmt(dr.eq)})` : 'No range' });\n  ag.checks.push({ label: 'OB created with displacement (FVG)', ok: !!ob && ob.displacement, req: false, w: 15, detail: ob ? (ob.displacement ? 'Impulse left imbalance' : 'Weak impulse') : '—' });\n  ag.checks.push({ label: 'Unmitigated (first touch)', ok: !!ob && ob.touches <= 1, req: false, w: 10, detail: ob ? `${ob.touches} touch(es)` : '—' });\n  ag.summary = ob ? `${ob.tf} order block in ${pdOK ? (D === 1 ? 'discount' : 'premium') : 'wrong zone'}.` : 'Price is not at institutional order flow.';\n  ag.ob = ob; ag.range = dr; ag.pos = pos;\n  return finish(ag);\n}\n\n// 5 ── MACRO: high-impact calendar blackout + world headline sentiment\nfunction newsAgent(asset, D, news) {\n  const ag = { id: 'news', name: 'World News Agent', tag: 'Calendar · Headlines', dir: D, checks: [] };\n  const curs = N.relevantCurrencies(asset);\n  const now = Date.now();\n  const cal = news.calendar || [];\n  const hits = cal.filter(e => e.impact === 'High' && (curs.includes(e.country) || e.country === 'All') && e.t - now < 60 * 60e3 && now - e.t < 30 * 60e3);\n  const next = cal.filter(e => e.impact === 'High' && (curs.includes(e.country) || e.country === 'All') && e.t > now).sort((a, b) => a.t - b.t)[0];\n  const sent = N.assetSentiment(asset, news.entities || {});\n  const heads = N.relevantHeadlines(asset, news.items || []);\n  const aligned = D !== 0 && sent * D >= -0.15;\n  ag.checks.push({ label: 'No high-impact event (−60m / +30m)', ok: hits.length === 0 && !news.calendarError, req: true, w: 45, detail: news.calendarError ? 'Calendar unavailable — blocked for safety' : hits.length ? hits.map(h => `${h.country} ${h.title} @ ${new Date(h.t).toUTCString().slice(17, 22)} UTC`).join('; ') : next ? `Next: ${next.country} ${next.title} in ${humanDur(next.t - now)}` : `No high-impact ${curs.join('/')} events this week` });\n  ag.checks.push({ label: 'Headline sentiment not against trade', ok: aligned, req: true, w: 35, detail: `Sentiment ${sent >= 0 ? '+' : ''}${sent.toFixed(2)} for ${asset.sym} from ${heads.length} relevant headline(s)` });\n  ag.checks.push({ label: 'Sentiment confirms direction', ok: D !== 0 && sent * D > 0.05, req: false, w: 20, detail: sent * D > 0.05 ? 'Tailwind' : 'Neutral / mixed' });\n  ag.summary = hits.length ? 'News blackout — high-impact release imminent.' : `Macro ${sent * D > 0.05 ? 'tailwind' : sent * D < -0.15 ? 'headwind' : 'neutral'} for ${dirWord(D)}.`;\n  ag.sentiment = sent; ag.headlines = heads; ag.nextEvent = next || null; ag.blackout = hits;\n  return finish(ag);\n}\n\n// 6 ── RISK: builds the plan and holds the VETO\nfunction riskAgent(asset, T, D, price, prior, liq, imb, obA, news, settings, ctx) {\n  const { h1, m15 } = T;\n  const ag = { id: 'risk', name: 'Risk Agent', tag: 'VETO · R:R · Sizing', dir: D, veto: true, checks: [] };\n  const a15 = m15.atr, a1 = h1.atr;\n  const prot = [];\n  if (obA.ob) prot.push(D === 1 ? obA.ob.bottom : obA.ob.top);\n  if (imb.zone) prot.push(D === 1 ? imb.zone.bottom : imb.zone.top);\n  if (liq.sweep && Math.abs(liq.sweep.wick - price) < 2.5 * a1) prot.push(liq.sweep.wick);\n  let plan = null;\n  if (D !== 0 && prot.length) {\n    const level = D === 1 ? Math.min(...prot) : Math.max(...prot);\n    const sl = level - D * 0.25 * a15;\n    const risk = Math.abs(price - sl);\n    const tg = (liq.targets || []).map(t => ({ ...t, rr: Math.abs(t.price - price) / risk })).sort((x, y) => x.rr - y.rr);\n    const main = tg.find(t => t.rr >= settings.minRR) || null;\n    const tp1 = tg[0] && tg[0] !== main ? tg[0] : { price: price + D * risk * 1.0, label: '1R', rr: 1 };\n    plan = { dir: dirWord(D), entry: price, sl, risk, tp1: tp1.price, tp1Label: tp1.label, tp2: main ? main.price : null, tp2Label: main ? main.label : null, rr: main ? main.rr : (tg.length ? tg[tg.length - 1].rr : 0) };\n    // position sizing (approx.)\n    const riskCash = settings.account * settings.riskPct / 100;\n    let qconv = 1;\n    if (asset.cls === 'forex' && asset.quote !== 'USD') {\n      if (asset.base === 'USD') qconv = 1 / price;\n      else if (ctx.prices['USD' + asset.quote]) qconv = 1 / ctx.prices['USD' + asset.quote];\n      else if (ctx.prices[asset.quote + 'USD']) qconv = ctx.prices[asset.quote + 'USD'];\n    }\n    const units = riskCash / (risk * qconv);\n    plan.riskCash = riskCash; plan.units = units;\n    plan.lots = asset.cls === 'forex' ? units / 100000 : asset.lot ? units / asset.lot : null;\n    plan.lotUnit = asset.cls === 'forex' ? 'std lots' : asset.lot ? asset.lotName : asset.ent;\n  }\n  const atrHist = h1.atrArr.slice(-100).filter(x => x != null).sort((x, y) => x - y);\n  const med = atrHist[Math.floor(atrHist.length / 2)] || a1;\n  const volRatio = a1 / med;\n  const lastT = m15.candles[m15.candles.length - 1].t;\n  const fresh = Date.now() - lastT < 2 * TF_MS['15m'] + 5 * 60e3;\n  const priorPass = prior.every(p => p.pass);\n  const conf = Math.round(prior.reduce((s, p) => s + p.score, 0) / prior.length);\n  ag.checks.push({ label: 'All 5 agents agree (consensus)', ok: priorPass && D !== 0, req: true, w: 20, detail: `${prior.filter(p => p.pass).length}/5 passed: ${prior.filter(p => !p.pass).map(p => p.name.replace(' Agent', '')).join(', ') || 'none failed'}` });\n  ag.checks.push({ label: 'Protective structure for stop', ok: !!plan, req: true, w: 10, detail: plan ? `SL ${fmt(plan.sl)} beyond ${obA.ob ? 'OB' : imb.zone ? 'FVG' : 'sweep'} (+0.25 ATR buffer)` : 'No invalidation level' });\n  ag.checks.push({ label: `Reward:Risk ≥ ${settings.minRR}`, ok: !!plan && plan.tp2 != null, req: true, w: 20, detail: plan ? (plan.tp2 != null ? `${plan.rr.toFixed(2)}R to ${plan.tp2Label} ${fmt(plan.tp2)}` : `Best ${plan.rr.toFixed(2)}R — not enough`) : '—' });\n  const slOK = plan && plan.risk >= 0.4 * a15 && plan.risk <= 2.5 * a1;\n  ag.checks.push({ label: 'Stop size sane (0.4×ATR15 – 2.5×ATR1H)', ok: !!slOK, req: true, w: 15, detail: plan ? `Stop ${fmt(plan.risk)} | ATR15 ${fmt(a15)} | ATR1H ${fmt(a1)}` : '—' });\n  ag.checks.push({ label: 'Volatility regime normal', ok: volRatio <= 2.2 && volRatio >= 0.35, req: true, w: 10, detail: `1H ATR is ${volRatio.toFixed(2)}× its 100-bar median` });\n  ag.checks.push({ label: 'Market open & data live', ok: fresh, req: true, w: 10, detail: fresh ? `Last tick ${humanDur(Date.now() - lastT)} ago` : 'Market closed / stale feed' });\n  ag.checks.push({ label: 'No news blackout', ok: !(news.blackout && news.blackout.length), req: true, w: 5, detail: news.blackout && news.blackout.length ? 'Blackout active' : 'Clear' });\n  ag.checks.push({ label: `Confluence score ≥ ${settings.minConf}`, ok: conf >= settings.minConf, req: true, w: 10, detail: `Average agent score ${conf}` });\n  ag.plan = plan; ag.confidence = conf;\n  finish(ag);\n  ag.summary = ag.pass ? `Approved: ${plan.rr.toFixed(1)}R, risking ${settings.riskPct}% (${plan.riskCash.toFixed(0)} USD).` : `VETO — ${ag.checks.filter(c => c.req && !c.ok).map(c => c.label).slice(0, 2).join('; ')}.`;\n  return ag;\n}\n\nlet FMT_DP = 2;\nfunction fmt(x) { return x == null || isNaN(x) ? '—' : Number(x).toFixed(FMT_DP); }\nfunction humanDur(ms) {\n  const m = Math.round(Math.abs(ms) / 60e3);\n  if (m < 60) return `${m}m`;\n  const h = Math.floor(m / 60);\n  return h < 48 ? `${h}h ${m % 60}m` : `${Math.floor(h / 24)}d ${h % 24}h`;\n}\n\n// Patch the forming candle of each timeframe with the latest live tick\nfunction applyLive(cs, tfMs, lp) {\n  if (!lp || !cs.length) return;\n  const last = cs[cs.length - 1];\n  if (last.closed || lp.t < last.t || lp.t >= last.t + tfMs) return;\n  last.c = lp.price; last.h = Math.max(last.h, lp.price); last.l = Math.min(last.l, lp.price);\n}\n\nfunction runSuperSix(asset, raw, news, settings, ctx) {\n  FMT_DP = asset.dp;\n  const lp = ctx.live || null;\n  if (lp) for (const tf of ['15m', '1h', '4h']) applyLive(raw[tf], TF_MS[tf], lp);\n  const T = { m15: analyzeTF(raw['15m'], '15m'), h1: analyzeTF(raw['1h'], '1h'), h4: analyzeTF(raw['4h'], '4h') };\n  const price = lp ? lp.price : T.m15.live.c;\n  const daily = S.dailyLevels(T.h1.closed);\n  const a1 = structureAgent(T);\n  const D = a1.dir;\n  const a2 = liquidityAgent(T, D, price, daily);\n  const a3 = imbalanceAgent(T, D, price);\n  const a4 = orderBlockAgent(T, D, price);\n  const a5 = newsAgent(asset, D, news);\n  const a6 = riskAgent(asset, T, D, price, [a1, a2, a3, a4, a5], a2, a3, a4, a5, settings, ctx);\n  const agents = [a1, a2, a3, a4, a5, a6];\n  const passCount = agents.filter(x => x.pass).length;\n  let status = 'NO TRADE';\n  if (passCount === 6) status = dirWord(D);\n  else if (D !== 0 && passCount >= 4) status = 'WATCH';\n  const ref = T.m15.closed[Math.max(0, T.m15.closed.length - 96)];\n  return {\n    sym: asset.sym, name: asset.name, cls: asset.cls, dp: asset.dp, price, dir: D, status, passCount,\n    change24: ref ? (price - ref.c) / ref.c * 100 : 0, ref24: ref ? ref.c : null, priceSrc: lp ? lp.src : 'candles', priceT: lp ? lp.t : T.m15.live.t,\n    trends: { '4h': T.h4.trend, '1h': T.h1.trend, '15m': T.m15.trend },\n    agents, plan: a6.pass ? a6.plan : a6.plan ? { ...a6.plan, provisional: true } : null,\n    confidence: a6.confidence, daily, T, updatedAt: Date.now(),\n  };\n}\n\n// Compact overlay payload for the chart\nfunction overlays(tfA, keep = 220) {\n  const total = tfA.candles.length;\n  const off = Math.max(0, total - keep);\n  const rel = i => (i == null ? null : i - off);\n  const candles = tfA.candles.slice(off).map(c => [c.t, c.o, c.h, c.l, c.c, c.closed ? 1 : 0]);\n  const px = tfA.live.c;\n  const fvg = tfA.fv.filter(z => z.i >= off - 150).slice(-12).map(z => ({ dir: z.dir, eff: z.eff, kind: z.kind, top: z.top, bottom: z.bottom, i: Math.max(0, rel(z.i)), filled: +z.filled.toFixed(2) }));\n  const ob = tfA.ob.filter(z => z.state !== 'broken' && z.i >= off - 150).slice(-6).map(z => ({ dir: z.dir, top: z.top, bottom: z.bottom, i: Math.max(0, rel(z.i)), state: z.state, touches: z.touches }));\n  const liq = {\n    bsl: tfA.lq.bsl.filter(l => l.i >= off && l.price >= px).sort((a, b) => a.price - b.price).slice(0, 3).map(l => ({ price: l.price, i: rel(l.i), count: l.count })),\n    ssl: tfA.lq.ssl.filter(l => l.i >= off && l.price <= px).sort((a, b) => b.price - a.price).slice(0, 3).map(l => ({ price: l.price, i: rel(l.i), count: l.count })),\n    sweeps: tfA.lq.sweeps.filter(s => s.at >= off).slice(-6).map(s => ({ side: s.side, price: s.price, from: Math.max(0, rel(s.from)), at: rel(s.at), wick: s.wick })),\n  };\n  const ev = tfA.st.events.filter(e => e.i >= off).slice(-8).map(e => ({ dir: e.dir, type: e.type, level: e.level, from: Math.max(0, rel(e.from)), i: rel(e.i) }));\n  const dr = tfA.dr ? { hi: tfA.dr.hi, lo: tfA.dr.lo, eq: tfA.dr.eq, from: Math.max(0, rel(tfA.dr.from)) } : null;\n  return { candles, fvg, ob, liq, ev, dr, atr: tfA.atr, trend: tfA.trend };\n}\n\nmodule.exports = { runSuperSix, overlays, applyLive };\n", "lib/data.js": "// Market data layer: OKX (crypto) + Yahoo Finance (forex / gold). No API keys needed.\nconst TF_MS = { '15m': 15 * 60e3, '1h': 60 * 60e3, '4h': 4 * 60 * 60e3 };\nconst TTL = { '15m': 20e3, '1h': 60e3, '4h': 180e3 };\n\nconst ASSETS = [\n  // ── Crypto (OKX, real-time)\n  { sym: 'BTCUSDT', name: 'Bitcoin', cls: 'crypto', src: 'okx', id: 'BTC-USDT', dp: 1, ent: 'BTC', tv: 'OKX:BTCUSDT' },\n  { sym: 'ETHUSDT', name: 'Ethereum', cls: 'crypto', src: 'okx', id: 'ETH-USDT', dp: 2, ent: 'ETH', tv: 'OKX:ETHUSDT' },\n  { sym: 'SOLUSDT', name: 'Solana', cls: 'crypto', src: 'okx', id: 'SOL-USDT', dp: 3, ent: 'SOL', tv: 'OKX:SOLUSDT' },\n  { sym: 'XRPUSDT', name: 'XRP', cls: 'crypto', src: 'okx', id: 'XRP-USDT', dp: 4, ent: 'XRP', tv: 'OKX:XRPUSDT' },\n  { sym: 'BNBUSDT', name: 'BNB', cls: 'crypto', src: 'okx', id: 'BNB-USDT', dp: 2, ent: 'BNB', tv: 'OKX:BNBUSDT' },\n  // ── Gold (OKX spot-tracking perpetual, real-time)\n  { sym: 'XAUUSD', name: 'Gold spot (XAU/USD)', cls: 'gold', src: 'okx', id: 'XAU-USDT-SWAP', dp: 2, base: 'XAU', quote: 'USD', ent: 'GOLD', lot: 100, lotName: 'lots (100 oz)', tv: 'OANDA:XAUUSD' },\n  // ── Commodities\n  { sym: 'XAGUSD', name: 'Silver (XAG/USD)', cls: 'commodity', src: 'okx', id: 'XAG-USDT-SWAP', dp: 3, ent: 'SILVER', lot: 5000, lotName: 'lots (5,000 oz)', tv: 'OANDA:XAGUSD' },\n  { sym: 'XPTUSD', name: 'Platinum (XPT/USD)', cls: 'commodity', src: 'okx', id: 'XPT-USDT-SWAP', dp: 1, ent: 'PLATINUM', lot: 50, lotName: 'lots (50 oz)', tv: 'OANDA:XPTUSD' },\n  { sym: 'USOIL', name: 'WTI Crude Oil', cls: 'commodity', src: 'okx', id: 'CL-USDT-SWAP', dp: 2, ent: 'OIL', lot: 1000, lotName: 'lots (1,000 bbl)', tv: 'TVC:USOIL' },\n  { sym: 'UKOIL', name: 'Brent Crude Oil', cls: 'commodity', src: 'yahoo', id: 'BZ=F', dp: 2, ent: 'OIL', lot: 1000, lotName: 'lots (1,000 bbl)', delay: 10, tv: 'TVC:UKOIL' },\n  { sym: 'NATGAS', name: 'Natural Gas', cls: 'commodity', src: 'yahoo', id: 'NG=F', dp: 3, ent: 'NATGAS', lot: 10000, lotName: 'lots (10,000 MMBtu)', delay: 10, tv: 'CAPITALCOM:NATURALGAS' },\n  { sym: 'COPPER', name: 'Copper', cls: 'commodity', src: 'yahoo', id: 'HG=F', dp: 4, ent: 'COPPER', lot: 25000, lotName: 'lots (25,000 lb)', delay: 10, tv: 'CAPITALCOM:COPPER' },\n  // ── Forex majors (Yahoo, near real-time)\n  { sym: 'EURUSD', name: 'Euro / US Dollar', cls: 'forex', src: 'yahoo', id: 'EURUSD=X', dp: 5, base: 'EUR', quote: 'USD', tv: 'OANDA:EURUSD' },\n  { sym: 'GBPUSD', name: 'Pound / US Dollar', cls: 'forex', src: 'yahoo', id: 'GBPUSD=X', dp: 5, base: 'GBP', quote: 'USD', tv: 'OANDA:GBPUSD' },\n  { sym: 'USDJPY', name: 'US Dollar / Yen', cls: 'forex', src: 'yahoo', id: 'USDJPY=X', dp: 3, base: 'USD', quote: 'JPY', tv: 'OANDA:USDJPY' },\n  { sym: 'AUDUSD', name: 'Aussie / US Dollar', cls: 'forex', src: 'yahoo', id: 'AUDUSD=X', dp: 5, base: 'AUD', quote: 'USD', tv: 'OANDA:AUDUSD' },\n  { sym: 'USDCAD', name: 'US Dollar / Loonie', cls: 'forex', src: 'yahoo', id: 'USDCAD=X', dp: 5, base: 'USD', quote: 'CAD', tv: 'OANDA:USDCAD' },\n  { sym: 'USDCHF', name: 'US Dollar / Franc', cls: 'forex', src: 'yahoo', id: 'USDCHF=X', dp: 5, base: 'USD', quote: 'CHF', tv: 'OANDA:USDCHF' },\n  { sym: 'NZDUSD', name: 'Kiwi / US Dollar', cls: 'forex', src: 'yahoo', id: 'NZDUSD=X', dp: 5, base: 'NZD', quote: 'USD', tv: 'OANDA:NZDUSD' },\n  // ── Forex crosses\n  { sym: 'GBPJPY', name: 'Pound / Yen', cls: 'forex', src: 'yahoo', id: 'GBPJPY=X', dp: 3, base: 'GBP', quote: 'JPY', tv: 'OANDA:GBPJPY' },\n  { sym: 'EURJPY', name: 'Euro / Yen', cls: 'forex', src: 'yahoo', id: 'EURJPY=X', dp: 3, base: 'EUR', quote: 'JPY', tv: 'OANDA:EURJPY' },\n  { sym: 'EURGBP', name: 'Euro / Pound', cls: 'forex', src: 'yahoo', id: 'EURGBP=X', dp: 5, base: 'EUR', quote: 'GBP', tv: 'OANDA:EURGBP' },\n  { sym: 'AUDJPY', name: 'Aussie / Yen', cls: 'forex', src: 'yahoo', id: 'AUDJPY=X', dp: 3, base: 'AUD', quote: 'JPY', tv: 'OANDA:AUDJPY' },\n  { sym: 'EURAUD', name: 'Euro / Aussie', cls: 'forex', src: 'yahoo', id: 'EURAUD=X', dp: 5, base: 'EUR', quote: 'AUD', tv: 'OANDA:EURAUD' },\n  { sym: 'GBPCHF', name: 'Pound / Franc', cls: 'forex', src: 'yahoo', id: 'GBPCHF=X', dp: 5, base: 'GBP', quote: 'CHF', tv: 'OANDA:GBPCHF' },\n  { sym: 'CADJPY', name: 'Loonie / Yen', cls: 'forex', src: 'yahoo', id: 'CADJPY=X', dp: 3, base: 'CAD', quote: 'JPY', tv: 'OANDA:CADJPY' },\n  { sym: 'CHFJPY', name: 'Franc / Yen', cls: 'forex', src: 'yahoo', id: 'CHFJPY=X', dp: 3, base: 'CHF', quote: 'JPY', tv: 'OANDA:CHFJPY' },\n  { sym: 'EURCAD', name: 'Euro / Loonie', cls: 'forex', src: 'yahoo', id: 'EURCAD=X', dp: 5, base: 'EUR', quote: 'CAD', tv: 'OANDA:EURCAD' },\n];\n\nconst cache = new Map();\nconst inflight = new Map();\n\nfunction withTimeout(p, ms, what) {\n  let t;\n  return Promise.race([p, new Promise((_, rej) => { t = setTimeout(() => rej(new Error('timeout: ' + what)), ms); })]).finally(() => clearTimeout(t));\n}\n\nasync function fetchText(url, ms = 15000, extraHeaders = {}) {\n  const ctrl = new AbortController();\n  const timer = setTimeout(() => ctrl.abort(), ms);\n  try {\n    return await withTimeout((async () => {\n      const r = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0 SuperSixDesk', 'Connection': 'close', ...extraHeaders }, signal: ctrl.signal });\n      if (!r.ok) throw new Error(`HTTP ${r.status} for ${url.split('?')[0]}`);\n      return r.text();\n    })(), ms + 1000, url.split('?')[0]);\n  } finally { clearTimeout(timer); ctrl.abort(); }\n}\n\nasync function getJSON(url) { return JSON.parse(await fetchText(url)); }\n\nasync function cached(key, ttl, fn) {\n  const hit = cache.get(key);\n  if (hit && Date.now() - hit.at < ttl) return hit.val;\n  if (inflight.has(key)) return inflight.get(key);\n  const p = withTimeout(Promise.resolve().then(fn), 25000, key).then(val => { cache.set(key, { at: Date.now(), val }); inflight.delete(key); return val; })\n    .catch(e => { inflight.delete(key); if (hit) return hit.val; throw e; });\n  inflight.set(key, p);\n  return p;\n}\n\nasync function okx(inst, tf) {\n  const bar = { '15m': '15m', '1h': '1H', '4h': '4H' }[tf];\n  return cached(`okx:${inst}:${tf}`, TTL[tf], async () => {\n    const j = await getJSON(`https://www.okx.com/api/v5/market/candles?instId=${inst}&bar=${bar}&limit=300`);\n    if (j.code !== '0') throw new Error('OKX: ' + j.msg);\n    return j.data.map(d => ({ t: +d[0], o: +d[1], h: +d[2], l: +d[3], c: +d[4], v: +d[5], closed: d[8] === '1' })).reverse();\n  });\n}\n\nfunction parseYahoo(j) {\n  const r = j.chart && j.chart.result && j.chart.result[0];\n  if (!r || !r.timestamp) throw new Error('Yahoo: empty result');\n  const q = r.indicators.quote[0];\n  const out = [];\n  r.timestamp.forEach((ts, i) => {\n    const o = q.open[i], h = q.high[i], l = q.low[i], c = q.close[i];\n    if (o == null || h == null || l == null || c == null) return;\n    out.push({ t: ts * 1000, o, h, l, c, v: (q.volume && q.volume[i]) || 0 });\n  });\n  return out;\n}\n\nfunction markClosed(cs, tf) {\n  const now = Date.now();\n  cs.forEach(c => { c.closed = c.t + TF_MS[tf] <= now; });\n  return cs;\n}\n\nfunction aggregate(cs, ms) {\n  const out = [];\n  let cur = null;\n  for (const c of cs) {\n    const b = Math.floor(c.t / ms) * ms;\n    if (!cur || cur.t !== b) { cur = { t: b, o: c.o, h: c.h, l: c.l, c: c.c, v: c.v }; out.push(cur); }\n    else { cur.h = Math.max(cur.h, c.h); cur.l = Math.min(cur.l, c.l); cur.c = c.c; cur.v += c.v; }\n  }\n  return out;\n}\n\nasync function yahoo(sym, tf) {\n  if (tf === '15m') {\n    return cached(`yh:${sym}:15m`, 28e3, async () => {\n      const j = await getJSON(`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(sym)}?interval=15m&range=5d`);\n      return markClosed(parseYahoo(j).slice(-300), '15m');\n    });\n  }\n  const h1 = await cached(`yh:${sym}:60m`, TTL['1h'], async () => {\n    const j = await getJSON(`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(sym)}?interval=60m&range=60d`);\n    return parseYahoo(j);\n  });\n  if (tf === '1h') return markClosed(h1.slice(-300).map(c => ({ ...c })), '1h');\n  return markClosed(aggregate(h1, TF_MS['4h']).slice(-300), '4h');\n}\n\nasync function getCandles(asset, tf) {\n  return asset.src === 'okx' ? okx(asset.id, tf) : yahoo(asset.id, tf);\n}\n\nmodule.exports = { ASSETS, TF_MS, getCandles, getJSON, fetchText, cached, withTimeout };\n", "lib/live.js": "// Fast live-price feed (independent of the slower agent scan).\n// Crypto + gold: OKX ticker every 3s.  Forex: one Yahoo batch request every 5s.\nconst { ASSETS, getJSON } = require('./data');\n\nconst prices = {};   // sym -> { price, bid, ask, t (exchange time), at (received), src }\nconst status = { okx: { ok: false, at: 0, err: null }, yahoo: { ok: false, at: 0, err: null } };\n\nasync function pollOKX() {\n  const list = ASSETS.filter(a => a.src === 'okx');\n  await Promise.all(list.map(async a => {\n    try {\n      const j = await getJSON(`https://www.okx.com/api/v5/market/ticker?instId=${a.id}`);\n      const d = j.data && j.data[0];\n      if (!d) throw new Error(j.msg || 'no data');\n      prices[a.sym] = { price: +d.last, bid: +d.bidPx, ask: +d.askPx, open24: +d.sodUtc0 || +d.open24h, t: +d.ts, at: Date.now(), src: 'OKX' };\n      status.okx = { ok: true, at: Date.now(), err: null };\n    } catch (e) { status.okx.err = e.message; }\n  }));\n}\n\nasync function pollYahoo() {\n  const list = ASSETS.filter(a => a.src === 'yahoo');\n  if (!list.length) return;\n  try {\n    const chunks = [];\n    for (let i = 0; i < list.length; i += 10) chunks.push(list.slice(i, i + 10));\n    const parts = await Promise.all(chunks.map(c => getJSON(`https://query1.finance.yahoo.com/v8/finance/spark?symbols=${c.map(a => encodeURIComponent(a.id)).join(',')}&range=1d&interval=1d`)));\n    const j = Object.assign({}, ...parts);\n    for (const a of list) {\n      const v = j[a.id];\n      if (!v || !v.close || !v.close.length) continue;\n      const price = v.close[v.close.length - 1];\n      if (price == null) continue;\n      prices[a.sym] = { price, t: v.timestamp[v.timestamp.length - 1] * 1000, at: Date.now(), src: 'Yahoo', prevClose: v.chartPreviousClose };\n    }\n    status.yahoo = { ok: true, at: Date.now(), err: null };\n  } catch (e) { status.yahoo.err = e.message; }\n}\n\nlet running = false;\nfunction start() {\n  if (running) return; running = true;\n  const loop = (fn, ms) => { const go = async () => { try { await fn(); } catch {} setTimeout(go, ms); }; go(); };\n  loop(pollOKX, 3000);\n  loop(pollYahoo, 5000);\n}\n\nfunction get(sym, maxAge = 30e3) { const p = prices[sym]; return p && Date.now() - p.at < maxAge ? p : null; }\n\nmodule.exports = { start, prices, status, get };\n", "lib/news.js": "// World news: ForexFactory economic calendar + multi-source RSS headline sentiment.\nconst { getJSON, fetchText, cached } = require('./data');\n\nconst FEEDS = [\n  { src: 'CoinDesk', url: 'https://www.coindesk.com/arc/outboundfeeds/rss/?outputType=xml' },\n  { src: 'Cointelegraph', url: 'https://cointelegraph.com/rss' },\n  { src: 'Investing.com', url: 'https://www.investing.com/rss/news_1.rss' },\n  { src: 'Yahoo Finance', url: 'https://feeds.finance.yahoo.com/rss/2.0/headline?s=GC=F,EURUSD=X,DX-Y.NYB,BTC-USD&region=US&lang=en-US' },\n  { src: 'Google News', url: 'https://news.google.com/rss/search?q=forex+dollar+OR+%22federal+reserve%22+OR+ECB+when:2d&hl=en-US&gl=US&ceid=US:en' },\n  { src: 'Google News', url: 'https://news.google.com/rss/search?q=%22gold+price%22+OR+bullion+when:2d&hl=en-US&gl=US&ceid=US:en' },\n  { src: 'Google News', url: 'https://news.google.com/rss/search?q=bitcoin+OR+crypto+market+when:2d&hl=en-US&gl=US&ceid=US:en' },\n  { src: 'Google News', url: 'https://news.google.com/rss/search?q=oil+price+OR+OPEC+OR+silver+price+OR+copper+OR+%22natural+gas%22+when:2d&hl=en-US&gl=US&ceid=US:en' },\n  { src: 'Google News', url: 'https://news.google.com/rss/search?q=yen+OR+sterling+OR+%22Bank+of+Japan%22+OR+%22Bank+of+England%22+when:2d&hl=en-US&gl=US&ceid=US:en' },\n];\n\nconst ENT = {\n  BTC: ['bitcoin', 'btc'], ETH: ['ethereum', 'ether', 'eth'], SOL: ['solana'], XRP: ['xrp', 'ripple'], BNB: ['bnb', 'binance coin'],\n  CRYPTO: ['crypto', 'cryptocurrency', 'cryptocurrencies', 'altcoin', 'altcoins', 'digital asset', 'stablecoin', 'spot etf'],\n  USD: ['dollar', 'usd', 'greenback', 'fed', 'federal reserve', 'powell', 'fomc', 'treasury yields', 'us cpi', 'nonfarm', 'payrolls', 'dxy'],\n  EUR: ['euro', 'eur', 'ecb', 'lagarde', 'eurozone'], GBP: ['pound', 'sterling', 'gbp', 'boe', 'bank of england', 'cable'],\n  JPY: ['yen', 'jpy', 'boj', 'bank of japan'], AUD: ['aussie', 'aud', 'rba', 'australian dollar'], CAD: ['loonie', 'cad', 'bank of canada', 'canadian dollar'],\n  CHF: ['swiss franc', 'chf', 'snb'], NZD: ['kiwi', 'nzd', 'rbnz', 'new zealand dollar'], GOLD: ['gold', 'xau', 'bullion'],\n  SILVER: ['silver', 'xag'], PLATINUM: ['platinum', 'xpt'], OIL: ['oil', 'crude', 'brent', 'wti', 'opec', 'opec+', 'barrel'], NATGAS: ['natural gas', 'natgas', 'lng'], COPPER: ['copper'],\n};\nconst CUR = ['USD', 'EUR', 'GBP', 'JPY', 'AUD', 'CAD', 'CHF', 'NZD'];\nconst BULL = ['surge', 'surges', 'soar', 'soars', 'rally', 'rallies', 'jump', 'jumps', 'gain', 'gains', 'climb', 'climbs', 'rise', 'rises', 'higher', 'record high', 'all-time high', 'bullish', 'rebound', 'rebounds', 'strengthens', 'strengthen', 'strong', 'firmer', 'upbeat', 'inflows', 'approval', 'approves', 'adoption', 'beats', 'breakout', 'recovers', 'advances', 'boost', 'boosts', 'tops', 'spikes', 'outperforms', 'buy'];\nconst BEAR = ['fall', 'falls', 'drop', 'drops', 'slump', 'slumps', 'plunge', 'plunges', 'tumble', 'tumbles', 'slide', 'slides', 'sink', 'sinks', 'lower', 'bearish', 'weak', 'weakens', 'weaker', 'crash', 'crashes', 'sell-off', 'selloff', 'outflows', 'hack', 'exploit', 'lawsuit', 'ban', 'misses', 'losses', 'declines', 'decline', 'retreat', 'retreats', 'slips', 'eases', 'liquidations', 'fears', 'recession', 'sheds', 'dips', 'sell'];\nconst HAWK = ['hawkish', 'rate hike', 'hikes rates', 'raise rates', 'tightening'];\nconst DOVE = ['dovish', 'rate cut', 'cuts rates', 'cut rates', 'easing', 'stimulus'];\n\nconst has = (txt, w) => new RegExp(`(^|[^a-z])${w.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')}([^a-z]|$)`).test(txt);\n\nfunction decode(s) {\n  return s.replace(/<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>/g, '$1').replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&quot;/g, '\"')\n    .replace(/&#39;|&apos;/g, \"'\").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#x27;/g, \"'\").trim();\n}\n\nfunction parseRSS(xml, src) {\n  const items = [];\n  const re = /<item[\\s>][\\s\\S]*?<\\/item>/g;\n  let m;\n  while ((m = re.exec(xml))) {\n    const it = m[0];\n    const g = tag => { const r = it.match(new RegExp(`<${tag}[^>]*>([\\\\s\\\\S]*?)</${tag}>`)); return r ? decode(r[1]) : ''; };\n    let title = g('title');\n    const pub = Date.parse(g('pubDate')) || Date.now();\n    let source = src;\n    const s = g('source'); if (s) source = s;\n    if (src === 'Google News') title = title.replace(/\\s+-\\s+[^-]+$/, '');\n    if (title) items.push({ title, link: g('link'), t: pub, source });\n  }\n  return items;\n}\n\nfunction scoreHeadline(title) {\n  const txt = ' ' + title.toLowerCase() + ' ';\n  let pol = 0;\n  BULL.forEach(w => { if (has(txt, w)) pol += 1; });\n  BEAR.forEach(w => { if (has(txt, w)) pol -= 1; });\n  pol = Math.max(-2, Math.min(2, pol));\n  const hawk = HAWK.some(w => has(txt, w)), dove = DOVE.some(w => has(txt, w));\n  const effects = {};\n  const add = (e, v) => { effects[e] = (effects[e] || 0) + v; };\n  // pair mentions like EUR/USD or USDJPY\n  const pairRe = /\\b(EUR|GBP|USD|AUD|NZD|CAD|CHF|JPY|XAU)\\s?\\/?\\s?(USD|JPY|CHF|CAD|GBP|EUR|AUD|NZD)\\b/g;\n  let pm, pairHit = false;\n  while ((pm = pairRe.exec(title.toUpperCase()))) {\n    if (pm[1] === pm[2]) continue;\n    pairHit = true;\n    const b = pm[1] === 'XAU' ? 'GOLD' : pm[1];\n    add(b, pol); add(pm[2], -pol);\n  }\n  const ents = Object.keys(ENT).filter(e => ENT[e].some(w => has(txt, w)));\n  if (!pairHit) ents.forEach(e => { if (pol) add(e, pol); });\n  // central-bank tone\n  ents.filter(e => CUR.includes(e)).forEach(e => {\n    if (hawk) { add(e, 1); if (e === 'USD') { add('GOLD', -0.5); add('CRYPTO', -0.5); } }\n    if (dove) { add(e, -1); if (e === 'USD') { add('GOLD', 0.5); add('CRYPTO', 0.5); } }\n  });\n  if (ents.includes('GOLD') && (hawk || dove) && !ents.some(e => CUR.includes(e))) add('GOLD', hawk ? -1 : 1);\n  return { pol, ents, effects };\n}\n\nasync function getHeadlines() {\n  return cached('news:headlines', 8 * 60e3, async () => {\n    const res = await Promise.allSettled(FEEDS.map(async f => {\n      return parseRSS(await fetchText(f.url, 12000), f.src);\n    }));\n    const seen = new Set(), all = [];\n    res.forEach(r => { if (r.status === 'fulfilled') r.value.forEach(it => {\n      const k = it.title.toLowerCase().slice(0, 70);\n      if (seen.has(k)) return; seen.add(k);\n      if (Date.now() - it.t > 48 * 3600e3) return;\n      all.push({ ...it, ...scoreHeadline(it.title) });\n    }); });\n    all.sort((a, b) => b.t - a.t);\n    return { items: all.slice(0, 250), sources: res.filter(r => r.status === 'fulfilled').length, total: FEEDS.length };\n  });\n}\n\n// Economic calendar: ForexFactory first; TradingView calendar as backup (cloud hosts are often rate-limited by ForexFactory).\nconst TV_CUR = { US: 'USD', EU: 'EUR', GB: 'GBP', JP: 'JPY', AU: 'AUD', NZ: 'NZD', CA: 'CAD', CH: 'CHF', CN: 'CNY' };\nconst TV_IMP = { '1': 'High', '0': 'Medium', '-1': 'Low' };\nlet ffBackoff = 0;\nasync function calFF() {\n  const j = await getJSON('https://nfs.faireconomy.media/ff_calendar_thisweek.json');\n  if (!Array.isArray(j) || !j.length) throw new Error('ForexFactory empty');\n  return j.map(e => ({ title: e.title, country: e.country, t: Date.parse(e.date), impact: e.impact, forecast: e.forecast, previous: e.previous, src: 'ForexFactory' }));\n}\nasync function calTV() {\n  const from = new Date(Date.now() - 2 * 86400e3).toISOString(), to = new Date(Date.now() + 8 * 86400e3).toISOString();\n  const url = `https://economic-calendar.tradingview.com/events?from=${from}&to=${to}&countries=${Object.keys(TV_CUR).join(',')}`;\n  const j = JSON.parse(await fetchText(url, 15000, { Origin: 'https://www.tradingview.com', Referer: 'https://www.tradingview.com/' }));\n  const r = (j && j.result) || [];\n  if (!r.length) throw new Error('TradingView calendar empty');\n  return r.map(e => ({ title: e.title, country: TV_CUR[e.country] || e.currency || e.country, t: Date.parse(e.date), impact: TV_IMP[String(e.importance)] || 'Low', forecast: e.forecast ?? '', previous: e.previous ?? '', src: 'TradingView' }));\n}\nasync function getCalendar() {\n  return cached('news:calendar', 30 * 60e3, async () => {\n    if (Date.now() > ffBackoff) {\n      try { return await calFF(); }\n      catch (e) { ffBackoff = Date.now() + 15 * 60e3; console.warn('[calendar] ForexFactory failed (' + e.message + '), using TradingView'); }\n    }\n    return calTV();\n  });\n}\n\nfunction entityScores(items) {\n  const acc = {};\n  const now = Date.now();\n  for (const it of items) {\n    const w = Math.exp(-(now - it.t) / (12 * 3600e3));\n    for (const [e, v] of Object.entries(it.effects)) {\n      acc[e] = acc[e] || { s: 0, w: 0, n: 0 };\n      acc[e].s += v * w; acc[e].w += w; acc[e].n++;\n    }\n  }\n  const out = {};\n  for (const [e, a] of Object.entries(acc)) out[e] = { score: Math.max(-1, Math.min(1, a.s / (a.w + 2))), n: a.n };\n  return out;\n}\n\nfunction relevantCurrencies(asset) {\n  if (asset.cls === 'crypto' || asset.cls === 'gold' || asset.cls === 'commodity') return ['USD'];\n  return [asset.base, asset.quote];\n}\n\nfunction assetSentiment(asset, ent) {\n  const g = e => (ent[e] ? ent[e].score : 0);\n  if (asset.cls === 'crypto') return 0.6 * g(asset.ent) + 0.4 * g('CRYPTO') - 0.15 * g('USD');\n  if (asset.cls === 'gold') return g('GOLD') - 0.5 * g('USD');\n  if (asset.cls === 'commodity') return g(asset.ent) - 0.4 * g('USD');\n  return g(asset.base) - g(asset.quote);\n}\n\nfunction relevantHeadlines(asset, items, max = 8) {\n  const keys = asset.cls === 'crypto' ? [asset.ent, 'CRYPTO'] : asset.cls === 'gold' || asset.cls === 'commodity' ? [asset.ent, 'USD'] : [asset.base, asset.quote];\n  return items.filter(it => keys.some(k => it.ents.includes(k) || it.effects[k] !== undefined)).slice(0, max);\n}\n\nmodule.exports = { getHeadlines, getCalendar, entityScores, assetSentiment, relevantCurrencies, relevantHeadlines };\n", "lib/smc.js": "// Smart Money Concepts engine: swings, BOS/CHoCH, liquidity & sweeps, FVG / iFVG, order blocks, premium/discount.\n\nfunction atr(c, p = 14) {\n  const out = new Array(c.length).fill(null);\n  let prev = null;\n  for (let i = 0; i < c.length; i++) {\n    const tr = i === 0 ? c[i].h - c[i].l\n      : Math.max(c[i].h - c[i].l, Math.abs(c[i].h - c[i - 1].c), Math.abs(c[i].l - c[i - 1].c));\n    if (i < p) { prev = prev == null ? tr : prev + tr; if (i === p - 1) { prev = prev / p; out[i] = prev; } }\n    else { prev = (prev * (p - 1) + tr) / p; out[i] = prev; }\n  }\n  return out;\n}\n\nfunction swings(c, len) {\n  const highs = [], lows = [];\n  for (let i = len; i < c.length - len; i++) {\n    let isH = true, isL = true;\n    for (let j = i - len; j <= i + len; j++) {\n      if (j === i) continue;\n      if (c[j].h > c[i].h || (j < i && c[j].h === c[i].h)) isH = false;\n      if (c[j].l < c[i].l || (j < i && c[j].l === c[i].l)) isL = false;\n      if (!isH && !isL) break;\n    }\n    if (isH) highs.push({ i, price: c[i].h, t: c[i].t });\n    if (isL) lows.push({ i, price: c[i].l, t: c[i].t });\n  }\n  return { highs, lows, len };\n}\n\n// Break of Structure / Change of Character using closes through confirmed swing points\nfunction structure(c, sw) {\n  const len = sw.len;\n  const ch = {}, cl = {};\n  sw.highs.forEach(p => (ch[p.i + len] = ch[p.i + len] || []).push({ ...p }));\n  sw.lows.forEach(p => (cl[p.i + len] = cl[p.i + len] || []).push({ ...p }));\n  let lastH = null, lastL = null, trend = 0;\n  const events = [];\n  for (let k = 0; k < c.length; k++) {\n    (ch[k] || []).forEach(p => { lastH = p; });\n    (cl[k] || []).forEach(p => { lastL = p; });\n    if (lastH && !lastH.broken && c[k].c > lastH.price) {\n      events.push({ i: k, t: c[k].t, dir: 1, type: trend === -1 ? 'CHoCH' : 'BOS', level: lastH.price, from: lastH.i });\n      lastH.broken = true; trend = 1;\n    }\n    if (lastL && !lastL.broken && c[k].c < lastL.price) {\n      events.push({ i: k, t: c[k].t, dir: -1, type: trend === 1 ? 'CHoCH' : 'BOS', level: lastL.price, from: lastL.i });\n      lastL.broken = true; trend = -1;\n    }\n  }\n  // consecutive same-direction breaks = trend strength\n  let streak = 0;\n  for (let e = events.length - 1; e >= 0 && events[e].dir === trend; e--) streak++;\n  return { events, trend, streak, last: events[events.length - 1] || null };\n}\n\n// Fair Value Gaps and their inversion (iFVG)\nfunction fvgs(c, atrArr, minFrac = 0.08) {\n  const n = c.length, out = [];\n  for (let i = 2; i < n; i++) {\n    const a = atrArr[i] || (c[i].h - c[i].l) || 1e-9;\n    if (c[i].l > c[i - 2].h && c[i].l - c[i - 2].h >= a * minFrac)\n      out.push({ dir: 1, top: c[i].l, bottom: c[i - 2].h, i: i - 1, t: c[i - 1].t });\n    if (c[i].h < c[i - 2].l && c[i - 2].l - c[i].h >= a * minFrac)\n      out.push({ dir: -1, top: c[i - 2].l, bottom: c[i].h, i: i - 1, t: c[i - 1].t });\n  }\n  for (const g of out) {\n    g.state = 'active'; g.filled = 0; g.lastTap = null; g.end = null;\n    const size = g.top - g.bottom;\n    for (let k = g.i + 2; k < n; k++) {\n      const x = c[k];\n      if (g.state === 'active') {\n        if (g.dir === 1 && x.l < g.top) {\n          g.filled = Math.max(g.filled, (g.top - Math.max(x.l, g.bottom)) / size); g.lastTap = k;\n          if (x.c < g.bottom) { g.state = 'inverted'; g.iDir = -1; g.invAt = k; g.lastTap = null; }\n        } else if (g.dir === -1 && x.h > g.bottom) {\n          g.filled = Math.max(g.filled, (Math.min(x.h, g.top) - g.bottom) / size); g.lastTap = k;\n          if (x.c > g.top) { g.state = 'inverted'; g.iDir = 1; g.invAt = k; g.lastTap = null; }\n        }\n      } else if (g.state === 'inverted') {\n        if (g.iDir === -1) { if (x.h >= g.bottom) g.lastTap = k; if (x.c > g.top) { g.state = 'dead'; g.end = k; break; } }\n        else { if (x.l <= g.top) g.lastTap = k; if (x.c < g.bottom) { g.state = 'dead'; g.end = k; break; } }\n      }\n    }\n    g.eff = g.state === 'inverted' ? g.iDir : g.dir;\n    g.kind = g.state === 'inverted' ? 'iFVG' : 'FVG';\n  }\n  return out.filter(g => g.state !== 'dead' && !(g.state === 'active' && g.filled >= 0.999));\n}\n\n// Order blocks: last opposite candle before the impulse leg that produced a BOS/CHoCH\nfunction orderBlocks(c, events, atrArr) {\n  const n = c.length, out = [];\n  for (const ev of events) {\n    let ext = ev.from;\n    for (let j = ev.from; j <= ev.i; j++) {\n      if (ev.dir === 1 ? c[j].l < c[ext].l : c[j].h > c[ext].h) ext = j;\n    }\n    let ob = -1;\n    for (let j = ext; j >= Math.max(0, ext - 6); j--) {\n      if (ev.dir === 1 ? c[j].c < c[j].o : c[j].c > c[j].o) { ob = j; break; }\n    }\n    if (ob < 0) ob = ext;\n    const top = ev.dir === 1 ? c[ob].h : Math.max(c[ob].h, c[ext].h);\n    const bottom = ev.dir === 1 ? Math.min(c[ob].l, c[ext].l) : c[ob].l;\n    // displacement quality: did the impulse leave an FVG?\n    let displacement = false;\n    for (let j = ext + 2; j <= ev.i && j < n; j++) {\n      if (ev.dir === 1 ? c[j].l > c[j - 2].h : c[j].h < c[j - 2].l) { displacement = true; break; }\n    }\n    const z = { dir: ev.dir, top, bottom, i: ob, t: c[ob].t, bosAt: ev.i, bosType: ev.type, displacement, state: 'fresh', touches: 0, lastTap: null, end: null };\n    let inZone = false;\n    for (let k = ev.i + 1; k < n; k++) {\n      const x = c[k];\n      const touching = ev.dir === 1 ? x.l <= top : x.h >= bottom;\n      if (touching) { if (!inZone) z.touches++; inZone = true; z.lastTap = k; } else inZone = false;\n      if (ev.dir === 1 ? x.c < bottom : x.c > top) { z.state = 'broken'; z.end = k; break; }\n    }\n    if (z.state !== 'broken' && z.touches > 0) z.state = 'mitigated';\n    out.push(z);\n  }\n  // dedupe overlapping same-direction blocks (keep most recent)\n  const res = [];\n  for (let k = out.length - 1; k >= 0; k--) {\n    const z = out[k];\n    if (res.some(r => r.dir === z.dir && r.i === z.i)) continue;\n    res.unshift(z);\n  }\n  return res;\n}\n\nfunction liquidity(c, sw, atrNow) {\n  const n = c.length, tol = (atrNow || 0) * 0.12;\n  const bsl = [], ssl = [], sweeps = [];\n  for (const p of sw.highs) {\n    let taken = null;\n    for (let k = p.i + 1; k < n; k++) if (c[k].h > p.price) { taken = k; break; }\n    if (taken === null) bsl.push({ price: p.price, i: p.i, t: p.t, count: 1 });\n    else if (c[taken].c < p.price) sweeps.push({ side: 'BSL', dir: -1, price: p.price, from: p.i, at: taken, t: c[taken].t, wick: c[taken].h });\n  }\n  for (const p of sw.lows) {\n    let taken = null;\n    for (let k = p.i + 1; k < n; k++) if (c[k].l < p.price) { taken = k; break; }\n    if (taken === null) ssl.push({ price: p.price, i: p.i, t: p.t, count: 1 });\n    else if (c[taken].c > p.price) sweeps.push({ side: 'SSL', dir: 1, price: p.price, from: p.i, at: taken, t: c[taken].t, wick: c[taken].l });\n  }\n  const cluster = (arr, up) => {\n    const s = [...arr].sort((a, b) => a.price - b.price), out = [];\n    for (const p of s) {\n      const last = out[out.length - 1];\n      if (last && Math.abs(p.price - last.price) <= tol) {\n        last.count++; last.i = Math.min(last.i, p.i);\n        last.price = up ? Math.max(last.price, p.price) : Math.min(last.price, p.price);\n      } else out.push({ ...p });\n    }\n    return out;\n  };\n  sweeps.sort((a, b) => a.at - b.at);\n  return { bsl: cluster(bsl, true), ssl: cluster(ssl, false), sweeps };\n}\n\nfunction dealingRange(c, st) {\n  const ev = st.last;\n  if (!ev) return null;\n  let hi = -Infinity, lo = Infinity;\n  for (let j = ev.from; j < c.length; j++) { hi = Math.max(hi, c[j].h); lo = Math.min(lo, c[j].l); }\n  return { hi, lo, eq: (hi + lo) / 2, from: ev.from };\n}\n\nfunction dailyLevels(c) {\n  const days = new Map();\n  for (const x of c) {\n    const d = new Date(x.t).toISOString().slice(0, 10);\n    const v = days.get(d);\n    if (!v) days.set(d, { h: x.h, l: x.l }); else { v.h = Math.max(v.h, x.h); v.l = Math.min(v.l, x.l); }\n  }\n  const keys = [...days.keys()].sort();\n  if (keys.length < 2) return null;\n  const pd = days.get(keys[keys.length - 2]);\n  return { pdh: pd.h, pdl: pd.l };\n}\n\nmodule.exports = { atr, swings, structure, fvgs, orderBlocks, liquidity, dealingRange, dailyLevels };\n", "public/index.html": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>SUPER SIX · SMC Signal Desk</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect width='32' height='32' rx='7' fill='%23f5c542'/><text x='16' y='23' font-size='18' font-family='Arial' font-weight='900' text-anchor='middle' fill='%23111'>6</text></svg>\">\n<style>\n:root{\n  --bg:#080a0f; --card:#0f141c; --card2:#141b26; --line:#1e2735; --line2:#2a3446;\n  --txt:#e9edf3; --mut:#8a94a6; --dim:#5d6779;\n  --buy:#19c98a; --buy2:rgba(25,201,138,.13); --sell:#f2465d; --sell2:rgba(242,70,93,.13);\n  --gold:#f5c542; --gold2:rgba(245,197,66,.12); --blue:#4b93ff; --amber:#ff9f1c; --violet:#a78bfa; --cyan:#22d3ee;\n  --mono: ui-monospace,\"SF Mono\",\"JetBrains Mono\",Menlo,Consolas,monospace;\n  --r:14px;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--bg);color:var(--txt);font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif}\nbutton,select,input{font:inherit;color:inherit}\n.mono{font-family:var(--mono);font-variant-numeric:tabular-nums}\n.up{color:var(--buy)} .dn{color:var(--sell)} .mut{color:var(--mut)} .gold{color:var(--gold)}\n.wrap{max-width:1480px;margin:0 auto;padding:0 20px}\n\n/* ── header ── */\nheader{border-bottom:1px solid var(--line);background:#0a0d13}\n.hbar{display:flex;align-items:center;gap:16px;padding-top:14px;padding-bottom:14px;flex-wrap:wrap}\n.brand{display:flex;align-items:center;gap:12px;margin-right:auto}\n.logo{width:40px;height:40px;border-radius:11px;background:var(--gold);color:#111;display:grid;place-items:center;font-weight:900;font-size:22px;box-shadow:0 0 26px rgba(245,197,66,.25)}\n.brand b{font-size:17px;letter-spacing:.14em;display:block}\n.brand small{color:var(--mut);font-size:11.5px;letter-spacing:.06em}\n.hright{display:flex;align-items:center;gap:10px;flex-wrap:wrap}\n.chip{display:inline-flex;align-items:center;gap:8px;padding:7px 12px;border:1px solid var(--line2);border-radius:999px;font-size:12.5px;color:var(--mut);background:var(--card)}\n.chip b{color:var(--txt);font-family:var(--mono);font-weight:600}\n.dot{width:8px;height:8px;border-radius:50%;background:var(--buy);animation:pulse 1.6s infinite}\n.dot.snap{background:var(--gold);animation:none}\n@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(25,201,138,.55)}70%{box-shadow:0 0 0 8px rgba(25,201,138,0)}100%{box-shadow:0 0 0 0 rgba(25,201,138,0)}}\n.btn{background:var(--card2);border:1px solid var(--line2);border-radius:10px;padding:8px 14px;cursor:pointer;font-size:13px;display:inline-flex;gap:6px;align-items:center}\n.btn:hover{border-color:#3d4a62}\n.btn.gold{background:var(--gold);color:#111;border-color:var(--gold);font-weight:700}\n\n/* ── nav ── */\nnav{position:sticky;top:0;z-index:20;background:rgba(8,10,15,.92);backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}\n.nav{display:flex;gap:4px;overflow-x:auto}\n.nav button{background:none;border:0;padding:14px 16px;cursor:pointer;color:var(--mut);font-size:14px;font-weight:600;border-bottom:2px solid transparent;white-space:nowrap;display:flex;align-items:center;gap:8px}\n.nav button.on{color:var(--txt);border-bottom-color:var(--gold)}\n.nav .cnt{font-size:11px;background:var(--card2);border:1px solid var(--line2);border-radius:999px;padding:0 7px;color:var(--mut)}\n.nav .cnt.hot{background:var(--buy);border-color:var(--buy);color:#04140d}\nsection.view{display:none;padding:22px 0 40px}\nsection.view.on{display:block}\nh3.sec{font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:var(--mut);margin:0 0 14px;font-weight:600;display:flex;align-items:center;gap:10px}\nh3.sec::after{content:\"\";flex:1;height:1px;background:var(--line)}\n\n/* ── summary strip ── */\n.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:22px}\n.stat{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:14px 16px}\n.stat span{display:block;font-size:11.5px;color:var(--mut);text-transform:uppercase;letter-spacing:.08em}\n.stat b{font-size:24px;font-family:var(--mono);font-weight:600}\n\n/* ── refresh panel ── */\n.refresh{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:16px 18px;margin-bottom:22px}\n.refresh .rh{display:flex;align-items:center;gap:10px;margin-bottom:12px;font-weight:700}\n.refresh .rh .mut{font-weight:400;font-size:12.5px}\n.rgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px}\n.ri{background:var(--card2);border:1px solid var(--line);border-radius:10px;padding:10px 12px}\n.ri span{display:block;font-size:11.5px;color:var(--mut)}\n.ri b{font-family:var(--mono);font-size:14px}\n.ri small{display:block;color:var(--dim);font-size:11px;margin-top:2px}\n.ri .bar{height:4px;background:#1b2230;border-radius:3px;margin-top:8px;overflow:hidden}\n.ri .bar i{display:block;height:100%;background:var(--buy);transition:width 1s linear}\n.spin{display:inline-block}\n.spin.go{animation:spin .8s linear}\n@keyframes spin{to{transform:rotate(360deg)}}\n.flash{animation:flash 1.2s ease}\n@keyframes flash{0%{background:rgba(25,201,138,.25)}100%{background:var(--card)}}\n.age{font-size:11px;color:var(--dim);font-family:var(--mono);display:flex;align-items:center;gap:5px;margin-top:2px}\n.age i{width:6px;height:6px;border-radius:50%;background:var(--buy);display:inline-block}\n.age.old i{background:var(--gold)} .age.dead i{background:var(--sell)}\n.tick-up{animation:tku .9s ease} .tick-dn{animation:tkd .9s ease}\n@keyframes tku{0%{color:#fff;background:rgba(25,201,138,.35)}100%{background:transparent}}\n@keyframes tkd{0%{color:#fff;background:rgba(242,70,93,.35)}100%{background:transparent}}\n#tvTape{border-bottom:1px solid var(--line);background:#0a0d13;min-height:46px}\n#tvTape.off{display:none}\n.tvbox{position:relative;height:clamp(420px,62vh,720px);background:#0b0f16}\n.tvbox .tradingview-widget-container{height:100%;width:100%}\n.tvnote{position:absolute;inset:0;display:grid;place-items:center;text-align:center;color:var(--mut);padding:30px;line-height:1.7}\n.delay{font-size:10.5px;color:var(--amber);border:1px solid rgba(255,159,28,.35);border-radius:5px;padding:1px 6px;margin-left:6px;font-weight:600;vertical-align:middle}\n.wsdot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--dim);margin-right:4px}\n.wsdot.on{background:var(--buy);box-shadow:0 0 6px var(--buy)}\n.banner.frozen{background:#4a1520;border-bottom:2px solid var(--sell);color:#ffd5db;padding:14px 18px;text-align:center;font-size:14px;line-height:1.6}\n.banner.frozen b{color:#fff;font-size:16px}\nbody.isfrozen .mc,body.isfrozen .verdict,body.isfrozen .plan,body.isfrozen .agents{filter:grayscale(.7);opacity:.6}\n.act{background:var(--card);border:1px solid var(--line);border-radius:var(--r);margin-bottom:22px;overflow:hidden}\n.act .ah{display:flex;justify-content:space-between;align-items:center;padding:12px 18px;border-bottom:1px solid var(--line);font-weight:700}\n.act .ah span{font-weight:400;color:var(--mut);font-size:12.5px}\n.act .list{max-height:230px;overflow:auto}\n.ai{display:grid;grid-template-columns:70px 90px 1fr auto;gap:12px;padding:9px 18px;border-bottom:1px solid #161d29;font-size:13px;align-items:center;cursor:pointer}\n.ai:hover{background:#121925}\n.ai .tm{font-family:var(--mono);color:var(--dim);font-size:12px}\n.chk{font-size:11.5px;color:var(--mut);font-family:var(--mono)}\n/* ── filters ── */\n.filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}\n.filters button{border:1px solid var(--line2);background:var(--card);border-radius:999px;padding:7px 15px;cursor:pointer;color:var(--mut);font-size:13px}\n.filters button.on{background:var(--txt);color:#0b0e14;border-color:var(--txt);font-weight:600}\n\n/* ── market cards ── */\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:16px}\n.mc{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:18px;cursor:pointer;transition:transform .12s,border-color .12s;position:relative;overflow:hidden}\n.mc:hover{transform:translateY(-2px);border-color:#38445a}\n.mc.BUY{border-color:rgba(25,201,138,.65);box-shadow:0 0 0 1px rgba(25,201,138,.25),0 10px 30px rgba(25,201,138,.08)}\n.mc.SELL{border-color:rgba(242,70,93,.65);box-shadow:0 0 0 1px rgba(242,70,93,.25),0 10px 30px rgba(242,70,93,.08)}\n.mc.WATCH{border-color:rgba(245,197,66,.45)}\n.mc .top{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}\n.mc .sym{font-size:17px;font-weight:800;letter-spacing:.02em}\n.mc .nm{color:var(--mut);font-size:12.5px}\n.mc .px{font-family:var(--mono);font-size:22px;font-weight:600;margin-top:12px}\n.mc .chg{font-family:var(--mono);font-size:12.5px}\n.badge{font-size:11.5px;font-weight:800;letter-spacing:.07em;padding:5px 10px;border-radius:7px;background:var(--card2);color:var(--mut);white-space:nowrap;border:1px solid var(--line2)}\n.badge.BUY{background:var(--buy);color:#04140d;border-color:var(--buy)}\n.badge.SELL{background:var(--sell);color:#fff;border-color:var(--sell)}\n.badge.WATCH{background:var(--gold2);color:var(--gold);border-color:rgba(245,197,66,.4)}\n.trs{display:flex;gap:6px;margin:14px 0}\n.tr{flex:1;text-align:center;font-size:12px;padding:5px 0;border-radius:8px;background:var(--card2);color:var(--mut);font-family:var(--mono)}\n.tr.b{color:var(--buy);background:var(--buy2)} .tr.s{color:var(--sell);background:var(--sell2)}\n.gates{display:grid;grid-template-columns:repeat(6,1fr);gap:5px}\n.gates div{text-align:center}\n.gates i{display:block;height:7px;border-radius:4px;background:#2a3240}\n.gates i.p{background:var(--buy)} .gates i.f{background:rgba(242,70,93,.55)}\n.gates small{display:block;font-size:9.5px;color:var(--dim);margin-top:4px;letter-spacing:.03em}\n.mc .foot{display:flex;justify-content:space-between;margin-top:12px;font-size:12px;color:var(--mut)}\n\n.how{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;margin-top:30px}\n.how div{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:14px 16px}\n.how b{display:flex;align-items:center;gap:8px;margin-bottom:4px}\n.how b i{font-style:normal;width:24px;height:24px;border-radius:7px;background:var(--card2);border:1px solid var(--line2);display:grid;place-items:center;font-size:12px}\n.how div.v{border-color:rgba(245,197,66,.45)} .how div.v b i{background:var(--gold);color:#111;border-color:var(--gold)}\n.how p{margin:0;color:var(--mut);font-size:12.5px}\n\n/* ── analysis ── */\n.ahead{display:flex;align-items:center;gap:18px;flex-wrap:wrap;margin-bottom:18px}\n.ahead select{background:var(--card);border:1px solid var(--line2);border-radius:10px;padding:9px 12px;font-weight:700;font-size:15px}\n.ahead .px{font-family:var(--mono);font-size:26px;font-weight:600}\n.ahead .nm{color:var(--mut);font-size:13px}\n.verdict{display:grid;grid-template-columns:auto 1fr;gap:22px;align-items:center;background:var(--card);border:1px solid var(--line2);border-radius:var(--r);padding:18px 22px;margin-bottom:18px}\n.verdict .v{font-size:34px;font-weight:900;letter-spacing:.08em;min-width:170px}\n.verdict.BUY{background:linear-gradient(90deg,rgba(25,201,138,.18),var(--card) 60%);border-color:rgba(25,201,138,.6)} .verdict.BUY .v{color:var(--buy)}\n.verdict.SELL{background:linear-gradient(90deg,rgba(242,70,93,.18),var(--card) 60%);border-color:rgba(242,70,93,.6)} .verdict.SELL .v{color:var(--sell)}\n.verdict.WATCH{border-color:rgba(245,197,66,.5)} .verdict.WATCH .v{color:var(--gold)}\n.verdict.NO .v{color:var(--mut);font-size:28px}\n.verdict .gates{gap:8px} .verdict .gates i{height:9px} .verdict .gates small{font-size:11px}\n.verdict p{margin:10px 0 0;color:var(--mut);font-size:13px}\n.plan{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:18px}\n.lv{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px 14px}\n.lv span{display:block;font-size:11.5px;color:var(--mut);text-transform:uppercase;letter-spacing:.07em}\n.lv b{font-family:var(--mono);font-size:17px;font-weight:600}\n.plan.dim .lv b{opacity:.5}\n.warn{grid-column:1/-1;background:var(--gold2);border:1px solid rgba(245,197,66,.35);color:var(--gold);border-radius:10px;padding:10px 14px;font-size:13px}\n.chartcard{background:var(--card);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;margin-bottom:24px}\n.ctool{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:12px 14px;border-bottom:1px solid var(--line)}\n.seg{display:flex;background:var(--bg);border:1px solid var(--line2);border-radius:10px;padding:3px}\n.seg button{border:0;background:none;padding:6px 14px;border-radius:7px;cursor:pointer;color:var(--mut);font-weight:600;font-size:13px}\n.seg button.on{background:var(--line2);color:var(--txt)}\n.toggles{display:flex;gap:6px;flex-wrap:wrap}\n.tg{font-size:12px;padding:6px 10px;border:1px solid var(--line2);border-radius:8px;cursor:pointer;color:var(--dim);background:transparent;display:inline-flex;align-items:center;gap:6px}\n.tg i{width:10px;height:10px;border-radius:3px;display:inline-block;opacity:.4}\n.tg.on{color:var(--txt);background:var(--card2)} .tg.on i{opacity:1}\n#chartWrap{position:relative;height:clamp(380px,58vh,660px)}\n#chart{position:absolute;inset:0;width:100%;height:100%;cursor:crosshair;touch-action:none}\n#ohlc{padding:8px 14px;font-family:var(--mono);font-size:12px;color:var(--mut);border-bottom:1px solid var(--line);min-height:34px}\n#chartMsg{position:absolute;inset:0;display:grid;place-items:center;color:var(--mut)}\n.hint{padding:8px 14px;font-size:11.5px;color:var(--dim);border-top:1px solid var(--line)}\n\n.agents{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:16px}\n.ag{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:16px 18px}\n.ag.pass{border-color:rgba(25,201,138,.35)} .ag.fail{border-color:rgba(242,70,93,.3)}\n.ag.veto{border-width:1.5px;border-color:rgba(245,197,66,.6);background:linear-gradient(180deg,rgba(245,197,66,.06),var(--card) 50%)}\n.ag .hd{display:flex;align-items:center;gap:12px}\n.ag .num{width:32px;height:32px;border-radius:10px;display:grid;place-items:center;font-weight:800;background:var(--card2);border:1px solid var(--line2)}\n.ag.pass .num{background:var(--buy);color:#04140d;border-color:var(--buy)} .ag.fail .num{background:#3a1d24;color:#ff8d9b;border-color:#5a2632}\n.ag .t{flex:1;min-width:0} .ag .t b{display:block;font-size:15px} .ag .t span{font-size:12px;color:var(--mut)}\n.pill{font-size:11.5px;font-weight:800;letter-spacing:.08em;padding:4px 10px;border-radius:999px}\n.pill.PASS{background:var(--buy2);color:var(--buy);border:1px solid rgba(25,201,138,.4)}\n.pill.FAIL{background:var(--sell2);color:var(--sell);border:1px solid rgba(242,70,93,.4)}\n.vtag{font-size:10px;font-weight:900;color:#111;background:var(--gold);padding:3px 7px;border-radius:5px;letter-spacing:.1em}\n.sbar{height:5px;background:#1b2230;border-radius:3px;margin:14px 0 10px;overflow:hidden}\n.sbar i{display:block;height:100%;border-radius:3px}\n.ag .sum{font-size:13.5px;color:#c9d0db;margin-bottom:10px}\n.ck{display:grid;grid-template-columns:20px 1fr;gap:2px 8px;padding:9px 0;border-top:1px solid #182030}\n.ck .ic{font-weight:900;text-align:center;font-size:14px}\n.ck .ic.ok{color:var(--buy)} .ck .ic.no{color:var(--sell)} .ck .ic.opt{color:var(--dim)}\n.ck .lb{display:flex;gap:8px;align-items:center;justify-content:space-between;font-size:13px}\n.ck .lb em{font-style:normal;font-size:9.5px;color:var(--dim);border:1px solid var(--line2);border-radius:4px;padding:0 5px;letter-spacing:.06em;flex-shrink:0}\n.ck .dt{grid-column:2;color:var(--mut);font-size:12px;font-family:var(--mono);word-break:break-word}\n.heads a{display:block;color:#b4bdca;text-decoration:none;font-size:12.5px;padding:7px 0;border-top:1px solid #182030}\n\n/* ── news / journal ── */\n.cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(420px,1fr));gap:20px}\n.panel{background:var(--card);border:1px solid var(--line);border-radius:var(--r);overflow:hidden}\n.panel .ph{padding:14px 18px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;font-weight:700}\n.panel .ph span{font-weight:400;color:var(--mut);font-size:12.5px}\n.tblwrap{overflow-x:auto}\ntable{width:100%;border-collapse:collapse;font-size:13px}\nth{text-align:left;font-weight:600;color:var(--mut);font-size:11px;letter-spacing:.08em;text-transform:uppercase;padding:10px 16px;border-bottom:1px solid var(--line);background:#0c1118}\ntd{padding:11px 16px;border-bottom:1px solid #161d29;white-space:nowrap}\ntr.clk{cursor:pointer} tr.clk:hover td{background:#121925}\n.oc{font-size:11px;font-weight:800;padding:3px 8px;border-radius:5px;letter-spacing:.05em}\n.oc.WIN{background:var(--buy2);color:var(--buy)} .oc.LOSS{background:var(--sell2);color:var(--sell)} .oc.OPEN{background:rgba(75,147,255,.15);color:var(--blue)} .oc.EXPIRED,.oc.BE{background:var(--card2);color:var(--mut)}\n.imp{width:9px;height:9px;border-radius:3px;display:inline-block;margin-right:8px}\n.imp.High{background:var(--sell)} .imp.Medium{background:var(--amber)}\n.hl{padding:13px 18px;border-bottom:1px solid #161d29;display:grid;grid-template-columns:1fr auto;gap:4px 14px}\n.hl a{color:#d6dce5;text-decoration:none;font-size:13.5px} .hl a:hover{color:#fff}\n.hl small{color:var(--dim);font-size:12px}\n.sent{font-size:10.5px;font-weight:800;padding:2px 8px;border-radius:5px;align-self:start}\n.sent.p{background:var(--buy2);color:var(--buy)} .sent.n{background:var(--sell2);color:var(--sell)} .sent.z{background:var(--card2);color:var(--mut)}\n.empty{padding:40px 20px;color:var(--mut);text-align:center;font-size:13.5px;line-height:1.7}\n\nfooter{border-top:1px solid var(--line);padding:16px 0 26px;color:var(--dim);font-size:12px}\nfooter .wrap{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}\n\n.modal{position:fixed;inset:0;background:rgba(0,0,0,.65);display:none;place-items:center;z-index:50;padding:20px}\n.modal.on{display:grid}\n.mbox{background:var(--card);border:1px solid var(--line2);border-radius:16px;padding:22px;width:min(420px,100%)}\n.mbox h3{margin:0 0 14px}\n.fld{display:flex;justify-content:space-between;align-items:center;margin:12px 0;gap:10px}\n.fld input{width:130px;background:var(--bg);border:1px solid var(--line2);border-radius:8px;padding:8px 10px;font-family:var(--mono);text-align:right}\n.mbox p{color:var(--mut);font-size:12.5px}\n#toasts{position:fixed;right:18px;top:18px;z-index:60;display:flex;flex-direction:column;gap:10px}\n.toast{background:var(--card2);border:1px solid var(--line2);border-left:4px solid var(--gold);padding:12px 16px;border-radius:12px;min-width:280px;box-shadow:0 12px 30px rgba(0,0,0,.5);animation:tin .3s ease}\n.toast.BUY{border-left-color:var(--buy)} .toast.SELL{border-left-color:var(--sell)}\n@keyframes tin{from{transform:translateX(30px);opacity:0}}\n.banner{background:var(--gold2);border-bottom:1px solid rgba(245,197,66,.35);color:var(--gold);font-size:12.5px;text-align:center;padding:7px 12px}\n.banner.saved{background:#141b26;color:#aeb8c8;border-bottom:1px solid #263142}\n.banner.err{background:#3a1d24;color:#ffd0d6;border-color:#f2465d}\n@media (max-width:640px){.wrap{padding:0 12px}.verdict{grid-template-columns:1fr}.cols{grid-template-columns:1fr}.verdict .v{font-size:28px}.agents{grid-template-columns:1fr}}\n::-webkit-scrollbar{width:9px;height:9px}::-webkit-scrollbar-thumb{background:#232c3b;border-radius:8px}::-webkit-scrollbar-track{background:transparent}\n</style>\n</head>\n<body>\n<div id=\"banners\"></div>\n<header><div class=\"wrap hbar\">\n  <div class=\"brand\"><div class=\"logo\">6</div><div><b>SUPER SIX</b><small>SMC multi-agent signal desk · Crypto · Forex · Gold · Commodities</small></div></div>\n  <div class=\"hright\">\n    <span class=\"chip\"><span class=\"dot\" id=\"liveDot\"></span><span id=\"modeTxt\">Live</span></span>\n    <span class=\"chip\" id=\"arChip\" title=\"Data refreshes automatically\"><span class=\"spin\" id=\"arIcon\">⟳</span> Auto-refresh <b id=\"arTxt\">ON</b></span>\n    <span class=\"chip\">Next scan <b id=\"hNext\">—</b></span>\n    <span class=\"chip\"><span id=\"hTz\">Local</span> <b id=\"hClock\">—</b></span>\n    <button class=\"btn\" id=\"bScan\">⟳ Scan now</button>\n    <button class=\"btn\" id=\"bSet\">⚙ Risk settings</button>\n  </div>\n</div></header>\n\n<div id=\"tvTape\" class=\"off\"></div>\n<nav><div class=\"wrap nav\" id=\"nav\">\n  <button data-v=\"board\" class=\"on\">📊 Signal Board <span class=\"cnt\" id=\"nSig\">0</span></button>\n  <button data-v=\"analysis\">📈 Chart &amp; Agents</button>\n  <button data-v=\"news\">🌍 News &amp; Calendar</button>\n  <button data-v=\"journal\">📒 Signal Journal <span class=\"cnt\" id=\"nJ\">0</span></button>\n</div></nav>\n\n<main class=\"wrap\">\n  <!-- BOARD -->\n  <section class=\"view on\" id=\"v-board\">\n    <div class=\"stats\">\n      <div class=\"stat\"><span>Live signals</span><b id=\"sSig\">0</b></div>\n      <div class=\"stat\"><span>On watch (4–5/6)</span><b id=\"sWatch\" class=\"gold\">0</b></div>\n      <div class=\"stat\"><span>Markets scanned</span><b id=\"sMk\">0</b></div>\n      <div class=\"stat\"><span>Journal win rate</span><b id=\"sWR\">—</b></div>\n    </div>\n    <div class=\"refresh\" id=\"refreshPanel\">\n      <div class=\"rh\"><span class=\"spin\" id=\"arIcon2\">⟳</span> Automatic refresh <span class=\"mut\" id=\"arMode\">Everything below updates by itself. No need to press anything.</span></div>\n      <div class=\"rgrid\">\n        <div class=\"ri\"><span>⚡ Live prices <span class=\"wsdot\" id=\"wsDot\"></span><span id=\"wsTxt\">OKX stream</span></span><b id=\"r0\">tick-by-tick</b><small id=\"r0s\">—</small><div class=\"bar\"><i id=\"r0b\" style=\"width:0\"></i></div></div>\n        <div class=\"ri\"><span>① Six agents re-check all 28 markets</span><b id=\"r1\">every 30s</b><small id=\"r1s\">—</small><div class=\"bar\"><i id=\"r1b\" style=\"width:0\"></i></div></div>\n        <div class=\"ri\"><span>② This page pulls fresh results</span><b id=\"r2\">every 15s</b><small id=\"r2s\">—</small><div class=\"bar\"><i id=\"r2b\" style=\"width:0\"></i></div></div>\n        <div class=\"ri\"><span>③ Chart &amp; agents for selected market</span><b id=\"r3\">every 20s</b><small id=\"r3s\">—</small><div class=\"bar\"><i id=\"r3b\" style=\"width:0\"></i></div></div>\n        <div class=\"ri\"><span>④ Candles: 15m / 1H / 4H</span><b>20s / 1m / 3m</b><small>re-fetched from OKX &amp; Yahoo on scan</small></div>\n        <div class=\"ri\"><span>⑤ World news · calendar</span><b>8 min · 30 min</b><small>headlines &amp; ForexFactory events</small></div>\n      </div>\n    </div>\n    <div class=\"act\"><div class=\"ah\">🤖 Agent activity <span id=\"actSub\">what changed on each scan</span></div><div class=\"list\" id=\"actList\"><div class=\"empty\" style=\"padding:18px\">Waiting for the next scan to compare…</div></div></div>\n    <div class=\"filters\" id=\"fTabs\">\n      <button data-f=\"all\" class=\"on\">All markets</button><button data-f=\"crypto\">Crypto</button><button data-f=\"forex\">Forex</button><button data-f=\"gold\">Gold</button><button data-f=\"commodity\">Commodities</button><button data-f=\"sig\">Signals &amp; Watch</button>\n    </div>\n    <div class=\"grid\" id=\"board\"><div class=\"empty\">Agents are scanning the markets…</div></div>\n\n    <h3 class=\"sec\" style=\"margin-top:34px\">How a signal is approved</h3>\n    <div class=\"how\">\n      <div><b><i>1</i>Structure</b><p>4H bias, 1H agrees, fresh 15m BOS/CHoCH in the same direction.</p></div>\n      <div><b><i>2</i>Liquidity</b><p>Stops swept against us, untouched liquidity left as the target.</p></div>\n      <div><b><i>3</i>FVG · iFVG</b><p>Price reacting from a fair value gap, path not blocked.</p></div>\n      <div><b><i>4</i>Order Block</b><p>Fresh OB at price, in discount for buys or premium for sells.</p></div>\n      <div><b><i>5</i>World News</b><p>No high-impact event near; headlines not against the trade.</p></div>\n      <div class=\"v\"><b><i>6</i>Risk · VETO</b><p>R:R ≥ 2, sane stop, normal volatility. If Risk fails, there is no trade.</p></div>\n    </div>\n  </section>\n\n  <!-- ANALYSIS -->\n  <section class=\"view\" id=\"v-analysis\">\n    <div class=\"ahead\">\n      <select id=\"symSel\"></select>\n      <div><div class=\"px\" id=\"cPx\">—</div><div class=\"nm\" id=\"cName\"></div></div>\n    </div>\n    <div id=\"verdict\"></div>\n    <div id=\"plan\"></div>\n    <div class=\"chartcard\">\n      <div class=\"ctool\" style=\"border-bottom:1px solid var(--line)\">\n        <div class=\"seg\" id=\"tfTabs\"><button data-tf=\"15m\" class=\"on\">15m</button><button data-tf=\"1h\">1H</button><button data-tf=\"4h\">4H</button></div>\n        <div class=\"seg\" id=\"modeTabs\"><button data-m=\"tv\" class=\"on\">📺 TradingView Live</button><button data-m=\"smc\">🧠 SMC Agent Chart</button></div>\n        <span class=\"mut\" id=\"modeHint\" style=\"font-size:12.5px\">Live TradingView feed. Switch to the SMC chart to see the agents' FVG, OB, liquidity and BOS drawings.</span>\n      </div>\n      <div id=\"tvPane\" class=\"tvbox\"><div class=\"tvnote\" id=\"tvNote\">Loading TradingView…</div></div>\n      <div id=\"smcPane\">\n      <div class=\"ctool\">\n        <div class=\"toggles\" id=\"ovTg\">\n          <button class=\"tg on\" data-o=\"bos\"><i style=\"background:#cfd6e0\"></i>BOS/CHoCH</button>\n          <button class=\"tg on\" data-o=\"liq\"><i style=\"background:var(--cyan)\"></i>Liquidity</button>\n          <button class=\"tg on\" data-o=\"fvg\"><i style=\"background:var(--buy)\"></i>FVG</button>\n          <button class=\"tg on\" data-o=\"ifvg\"><i style=\"background:var(--violet)\"></i>iFVG</button>\n          <button class=\"tg on\" data-o=\"ob\"><i style=\"background:var(--blue)\"></i>Order Blocks</button>\n          <button class=\"tg\" data-o=\"pd\"><i style=\"background:var(--gold)\"></i>Premium/Discount</button>\n          <button class=\"tg on\" data-o=\"plan\"><i style=\"background:#fff\"></i>Trade levels</button>\n        </div>\n      </div>\n      <div id=\"ohlc\"></div>\n      <div id=\"chartWrap\"><canvas id=\"chart\"></canvas><div id=\"chartMsg\">Pick a market on the Signal Board</div></div>\n      <div class=\"hint\">Scroll to zoom · drag to pan · double-click to reset · switch drawings on/off above</div>\n      </div>\n    </div>\n    <h3 class=\"sec\">The six agents <span id=\"agDir\" class=\"mono\" style=\"text-transform:none;letter-spacing:0\"></span></h3>\n    <div class=\"agents\" id=\"agents\"></div>\n  </section>\n\n  <!-- NEWS -->\n  <section class=\"view\" id=\"v-news\">\n    <div class=\"cols\">\n      <div class=\"panel\"><div class=\"ph\">Economic calendar <span>High &amp; medium impact · your local time</span></div><div class=\"tblwrap\" id=\"cal\"></div></div>\n      <div class=\"panel\"><div class=\"ph\">World headlines <span id=\"nSrc\"></span></div><div id=\"heads\"></div></div>\n    </div>\n  </section>\n\n  <!-- JOURNAL -->\n  <section class=\"view\" id=\"v-journal\">\n    <div class=\"panel\"><div class=\"ph\">Signal journal <span id=\"jStats\"></span></div><div class=\"tblwrap\" id=\"journal\"></div></div>\n  </section>\n</main>\n\n<footer><div class=\"wrap\"><span>Data: OKX (crypto) · Yahoo Finance (forex, COMEX gold) · ForexFactory calendar · CoinDesk, Cointelegraph, Investing.com, Yahoo, Google News</span><span>Educational tool, not financial advice. No signal is guaranteed.</span></div></footer>\n\n<div class=\"modal\" id=\"mSet\"><div class=\"mbox\">\n  <h3>Risk Agent settings</h3>\n  <div class=\"fld\"><label>Account size (USD)</label><input id=\"sAcc\" type=\"number\" step=\"100\"></div>\n  <div class=\"fld\"><label>Risk per trade (%)</label><input id=\"sRisk\" type=\"number\" step=\"0.1\"></div>\n  <div class=\"fld\"><label>Minimum reward : risk</label><input id=\"sRR\" type=\"number\" step=\"0.1\"></div>\n  <div class=\"fld\"><label>Min confluence score</label><input id=\"sConf\" type=\"number\" step=\"1\"></div>\n  <p>The Risk agent vetoes any setup that breaks these limits, even if the other five agents agree.</p>\n  <div style=\"display:flex;gap:8px;justify-content:flex-end\"><button class=\"btn\" id=\"sCancel\">Cancel</button><button class=\"btn gold\" id=\"sSave\">Save &amp; rescan</button></div>\n</div></div>\n<div id=\"toasts\"></div>\n\n<script>\nconst $ = s => document.querySelector(s);\nconst AG_SHORT = ['Structure', 'Liquidity', 'FVG', 'OB', 'News', 'Risk'];\nconst SNAP = window.__SNAPSHOT__ || null;\nlet desk = null, sel = null, detail = null, tf = '15m', filter = 'all', viewName = 'board';\nconst ov = { bos: 1, liq: 1, fvg: 1, ifvg: 1, ob: 1, pd: 0, plan: 1 };\nlet view = { end: null, count: 100 }, mouse = null, seenSignals = null;\nlet lastDeskFetch = 0, lastDetailFetch = 0, prevScan = 0, lastPriceFetch = 0, livePrices = {}, clockSkew = 0;\nconst TFMS = { '15m': 9e5, '1h': 36e5, '4h': 144e5 };\nfunction flash(el, up) { if (!el) return; el.classList.remove('tick-up', 'tick-dn'); void el.offsetWidth; el.classList.add(up ? 'tick-up' : 'tick-dn'); }\nfunction patchCandles(d, lp) {\n  if (!d || !lp) return;\n  for (const t of ['15m', '1h', '4h']) {\n    const C = d.charts[t] && d.charts[t].candles; if (!C || !C.length) continue;\n    const k = C[C.length - 1];\n    if (k[5] || lp.t < k[0] || lp.t >= k[0] + TFMS[t]) continue;\n    k[4] = lp.price; k[2] = Math.max(k[2], lp.price); k[3] = Math.min(k[3], lp.price);\n  }\n}\nfunction applyPrice(sym, lp) {\n  const a = desk && desk.assets.find(x => x.sym === sym); if (!a || a.pending) return;\n  const old = a.price; a.priceAt = lp.at; if (lp.price === old && a.priceT === lp.t) return;\n  a.price = lp.price; a.priceT = lp.t; a.priceAt = lp.at; a.priceSrc = lp.src;\n  if (a.ref24) a.change24 = (lp.price - a.ref24) / a.ref24 * 100;\n  const pe = document.querySelector(`[data-px=\"${sym}\"]`), ce = document.querySelector(`[data-chg=\"${sym}\"]`);\n  if (pe) { pe.textContent = fmt(a.price, a.dp); if (lp.price !== old) flash(pe, lp.price > old); }\n  if (ce) { ce.textContent = `${a.change24 >= 0 ? '+' : ''}${a.change24.toFixed(2)}% · 24h`; ce.className = 'chg ' + (a.change24 >= 0 ? 'up' : 'dn'); }\n  if (detail && detail.sym === sym) {\n    const o = detail.price; detail.price = lp.price; detail.change24 = a.change24; detail.priceT = lp.t;\n    patchCandles(detail, lp);\n    $('#cPx').innerHTML = `<span id=\"cPxV\">${fmt(detail.price, detail.dp)}</span> <span class=\"${detail.change24 >= 0 ? 'up' : 'dn'}\" style=\"font-size:14px\">${detail.change24 >= 0 ? '+' : ''}${detail.change24.toFixed(2)}%</span>`;\n    if (lp.price !== o) flash($('#cPxV'), lp.price > o);\n    drawChart();\n  }\n}\nfunction updateAges() {\n  if (!desk) return;\n  const now = Date.now() - clockSkew;\n  for (const a of desk.assets) { const c = document.querySelector(`[data-chk=\"${a.sym}\"]`); if (c && a.updatedAt) c.textContent = secs(now - a.updatedAt); }\n  const ag = $('#agAge'); if (ag && detail) ag.textContent = secs(now - detail.updatedAt);\n  for (const a of desk.assets) {\n    const el = document.querySelector(`[data-age=\"${a.sym}\"]`); if (!el || !a.priceT) continue;\n    const checked = now - (a.priceAt || a.priceT), quoteAge = now - a.priceT - (a.delay || 0) * 60e3;\n    const dead = checked > 120e3 || quoteAge > 600e3, old = !dead && (checked > 40e3 || quoteAge > 180e3);\n    el.className = 'age' + (dead ? ' dead' : old ? ' old' : '');\n    el.querySelector('span').textContent = dead\n      ? (quoteAge > 600e3 && checked < 120e3 ? `MARKET QUIET · last quote ${secs(quoteAge)} ago` : `STALE · price from ${secs(checked)} ago`)\n      : (wsLast[a.sym] && Date.now() - wsLast[a.sym] < 10e3 ? `LIVE · OKX stream · tick ${secs(Date.now() - wsLast[a.sym])} ago` : `${a.delay ? 'DELAYED ' + a.delay + 'm' : 'LIVE'} · ${a.priceSrc || ''} · checked ${secs(Math.max(0, checked))} ago`);\n  }\n}\nasync function pollPrices() {\n  if (SNAP) return;\n  try {\n    const r = await api('api/prices');\n    clockSkew = Date.now() - r.now; lastPriceFetch = Date.now(); livePrices = r.prices;\n    for (const [sym, lp] of Object.entries(r.prices)) {\n      if (wsLast[sym] && Date.now() - wsLast[sym] < 8000) continue;   // stream is fresher\n      applyPrice(sym, lp);\n    }\n  } catch {}\n}\n\n/* OKX public WebSocket: tick-by-tick prices for crypto, gold, silver, platinum, oil */\nconst wsLast = {}; let ws = null, wsTicks = 0, wsPing = null;\nfunction startWS() {\n  if (SNAP || ws || !desk || !window.WebSocket) return;\n  const okx = desk.assets.filter(a => a.src === 'okx' && a.id);\n  if (!okx.length) return;\n  const byId = Object.fromEntries(okx.map(a => [a.id, a.sym]));\n  try { ws = new WebSocket('wss://ws.okx.com:8443/ws/v5/public'); } catch { ws = null; return; }\n  ws.onopen = () => {\n    ws.send(JSON.stringify({ op: 'subscribe', args: okx.map(a => ({ channel: 'tickers', instId: a.id })) }));\n    wsPing = setInterval(() => { try { ws.send('ping'); } catch {} }, 20000);\n  };\n  ws.onmessage = e => {\n    if (e.data === 'pong') return;\n    let m; try { m = JSON.parse(e.data); } catch { return; }\n    if (!m.data) return;\n    for (const d of m.data) {\n      const sym = byId[d.instId]; if (!sym) continue;\n      wsLast[sym] = Date.now(); wsTicks++;\n      applyPrice(sym, { price: +d.last, t: +d.ts, at: Date.now() - clockSkew, src: 'OKX' });\n    }\n  };\n  ws.onclose = ws.onerror = () => { clearInterval(wsPing); try { ws.close(); } catch {} ws = null; setTimeout(startWS, 5000); };\n}\nsetInterval(() => {\n  if (SNAP) return;\n  const on = Object.values(wsLast).some(t => Date.now() - t < 10e3);\n  const dot = $('#wsDot'); if (dot) dot.classList.toggle('on', on);\n  const tx = $('#wsTxt'); if (tx) tx.textContent = on ? `stream ON · ${wsTicks} ticks` : 'stream connecting…';\n}, 1000);\n\n/* TradingView widgets (need internet: live preview or your own computer) */\nlet tvMode = SNAP ? 'smc' : 'tv', tvKey = '';\nfunction tvScript(src, cfg, host) {\n  host.innerHTML = '<div class=\"tradingview-widget-container\"><div class=\"tradingview-widget-container__widget\" style=\"height:100%;width:100%\"></div></div>';\n  const sc = document.createElement('script');\n  sc.type = 'text/javascript'; sc.async = true; sc.src = src; sc.innerHTML = JSON.stringify(cfg);\n  host.firstChild.appendChild(sc);\n}\nfunction startTape() {\n  if (SNAP || !desk || $('#tvTape').dataset.on) return;\n  const pick = ['BTCUSDT', 'ETHUSDT', 'SOLUSDT', 'XAUUSD', 'XAGUSD', 'USOIL', 'UKOIL', 'EURUSD', 'GBPUSD', 'USDJPY', 'GBPJPY', 'AUDUSD', 'EURJPY', 'NATGAS', 'COPPER'];\n  const syms = pick.map(p => desk.assets.find(a => a.sym === p)).filter(Boolean).map(a => ({ proName: a.tv, title: a.sym }));\n  $('#tvTape').classList.remove('off'); $('#tvTape').dataset.on = 1;\n  tvScript('https://s3.tradingview.com/external-embedding/embed-widget-ticker-tape.js', { symbols: syms, showSymbolLogo: true, isTransparent: true, displayMode: 'adaptive', colorTheme: 'dark', locale: 'en' }, $('#tvTape'));\n}\nfunction renderTV() {\n  const pane = $('#tvPane');\n  if (tvMode !== 'tv') return;\n  if (SNAP) { pane.innerHTML = '<div class=\"tvnote\"><div><b style=\"color:var(--txt)\">TradingView live charts need internet.</b><br>This file viewer is offline, so they can\\'t load here.<br>Open the <b>live preview</b> or run the desk on your computer to see TradingView moving tick by tick.<br><br>The <b>SMC Agent Chart</b> tab works here.</div></div>'; return; }\n  const a = desk && desk.assets.find(x => x.sym === sel); if (!a || !a.tv) return;\n  const iv = { '15m': '15', '1h': '60', '4h': '240' }[tf];\n  const key = a.tv + iv; if (key === tvKey && pane.querySelector('iframe')) return; tvKey = key;\n  tvScript('https://s3.tradingview.com/external-embedding/embed-widget-advanced-chart.js', {\n    autosize: true, symbol: a.tv, interval: iv, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'Etc/UTC',\n    theme: 'dark', style: '1', locale: 'en', backgroundColor: '#0b0f16', gridColor: 'rgba(40,50,70,0.35)',\n    allow_symbol_change: true, hide_side_toolbar: false, withdateranges: true, details: true, calendar: false, support_host: 'https://www.tradingview.com'\n  }, pane);\n}\nfunction setMode(m) {\n  tvMode = m;\n  document.querySelectorAll('#modeTabs button').forEach(b => b.classList.toggle('on', b.dataset.m === m));\n  $('#tvPane').style.display = m === 'tv' ? '' : 'none';\n  $('#smcPane').style.display = m === 'smc' ? '' : 'none';\n  $('#modeHint').textContent = m === 'tv' ? 'Live TradingView feed. Switch to the SMC chart to see the agents\\' FVG, OB, liquidity and BOS drawings.' : 'The agents\\' view: BOS/CHoCH, liquidity, FVG/iFVG, order blocks and trade levels, updated live.';\n  if (m === 'tv') renderTV(); else requestAnimationFrame(drawChart);\n}\n$('#modeTabs').onclick = e => { const b = e.target.closest('button'); if (b) setMode(b.dataset.m); };\nfunction spinIcons() { ['#arIcon', '#arIcon2'].forEach(id => { const el = $(id); el.classList.remove('go'); void el.offsetWidth; el.classList.add('go'); }); }\n\nconst fmt = (x, dp) => x == null || isNaN(x) ? '—' : Number(x).toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp });\nconst ago = t => { const m = Math.round((Date.now() - t) / 60000); return m < 1 ? 'just now' : m < 60 ? m + 'm ago' : m < 1440 ? Math.floor(m / 60) + 'h ago' : Math.floor(m / 1440) + 'd ago'; };\nconst tstr = t => new Date(t).toLocaleString([], { weekday: 'short', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false });\nconst esc = s => String(s ?? '').replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\nconst arrow = d => d === 1 ? '▲' : d === -1 ? '▼' : '◆';\nconst tfL = t => t === '15m' ? '15m' : t.toUpperCase();\n\nasync function api(p, opt) {\n  if (SNAP) {\n    if (p.startsWith('api/desk')) return SNAP.desk;\n    if (p.startsWith('api/asset')) { const a = SNAP.assets[decodeURIComponent(p.split('sym=')[1])]; if (!a) throw new Error('n/a'); return a; }\n    throw new Error('snapshot mode');\n  }\n  const r = await fetch(p, opt); if (!r.ok) throw new Error(r.status); return r.json();\n}\nfunction banner(id, html, cls) { let b = document.getElementById(id); if (!html) { b && b.remove(); return; } if (!b) { b = document.createElement('div'); b.id = id; $('#banners').appendChild(b); } b.className = 'banner ' + (cls || ''); b.innerHTML = html; }\n\n/* ── navigation ── */\nfunction go(v) {\n  viewName = v;\n  document.querySelectorAll('#nav button').forEach(b => b.classList.toggle('on', b.dataset.v === v));\n  document.querySelectorAll('section.view').forEach(s => s.classList.toggle('on', s.id === 'v-' + v));\n  if (v === 'analysis') { requestAnimationFrame(drawChart); renderTV(); }\n  window.scrollTo({ top: 0 });\n}\n$('#nav').onclick = e => { const b = e.target.closest('button'); if (b) go(b.dataset.v); };\n\n/* ── data ── */\nasync function loadDesk() {\n  try {\n    desk = await api('api/desk');\n    banner('connErr', null);\n    lastDeskFetch = Date.now(); spinIcons();\n    if (prevScan && desk.lastScan !== prevScan) { const rp = $('#refreshPanel'); rp.classList.remove('flash'); void rp.offsetWidth; rp.classList.add('flash'); }\n    prevScan = desk.lastScan;\n    if (desk.now && !SNAP) clockSkew = Date.now() - desk.now;\n    if (!SNAP) { startWS(); startTape(); }\n    renderStats(); renderBoard(); updateAges(); renderActivity(); checkFrozen(); renderJournal(); renderCal(); renderHeads(); fillSelect(); checkNewSignals();\n    if (sel && !detail) { $('#symSel').value = sel; loadDetail(); }\n    if (!sel) { const sorted = sortAssets(desk.assets.filter(a => !a.pending)); if (sorted[0]) choose(sorted[0].sym, false); }\n  } catch (e) { banner('connErr', 'Desk server not reachable. Retrying every 15 seconds…', 'err'); }\n}\nasync function loadDetail() {\n  if (!sel) return;\n  try {\n    const d = await api('api/asset?sym=' + encodeURIComponent(sel));\n    if (!detail || detail.sym !== d.sym) view = { end: null, count: 100 };\n    detail = d; lastDetailFetch = Date.now(); renderDetail(); drawChart();\n  } catch { $('#chartMsg').style.display = 'grid'; $('#chartMsg').textContent = 'Agents are still analysing ' + sel + '…'; }\n}\nfunction choose(sym, open = true) { sel = sym; detail = null; $('#symSel').value = sym; setTimeout(renderTV, 0); $('#chartMsg').style.display = 'grid'; $('#chartMsg').textContent = 'Loading ' + sym + '…'; loadDetail(); if (open) go('analysis'); }\n\nconst rankOf = a => a.status === 'BUY' || a.status === 'SELL' ? 0 : a.status === 'WATCH' ? 1 : 2;\nconst sortAssets = list => [...list].sort((a, b) => rankOf(a) - rankOf(b) || (b.passCount || 0) - (a.passCount || 0));\n\nfunction renderStats() {\n  const live = desk.assets.filter(a => a.status === 'BUY' || a.status === 'SELL').length;\n  const watch = desk.assets.filter(a => a.status === 'WATCH').length;\n  $('#sSig').textContent = live; $('#sSig').className = live ? 'up' : '';\n  $('#sWatch').textContent = watch;\n  $('#sMk').textContent = desk.assets.filter(a => !a.pending).length + ' / ' + desk.assets.length;\n  const s = desk.stats; $('#sWR').textContent = s.winRate != null ? s.winRate + '%' : '—';\n  $('#nSig').textContent = live; $('#nSig').classList.toggle('hot', live > 0);\n  $('#nJ').textContent = s.total;\n}\n\nfunction gatesHTML(agents) {\n  return '<div class=\"gates\">' + AG_SHORT.map((n, i) => { const g = agents && agents[i]; return `<div><i class=\"${g ? (g.pass ? 'p' : 'f') : ''}\"></i><small>${n}</small></div>`; }).join('') + '</div>';\n}\nfunction renderBoard() {\n  let list = desk.assets;\n  if (filter === 'sig') list = list.filter(a => ['BUY', 'SELL', 'WATCH'].includes(a.status));\n  else if (filter !== 'all') list = list.filter(a => a.cls === filter);\n  list = sortAssets(list);\n  if (!list.length) { $('#board').innerHTML = `<div class=\"empty\" style=\"grid-column:1/-1\">${filter === 'sig' ? 'No market is close to a signal right now. The desk waits for all six agents to agree.' : 'No markets here.'}</div>`; return; }\n  $('#board').innerHTML = list.map(a => {\n    if (a.pending) return `<div class=\"mc\" data-s=\"${a.sym}\"><div class=\"top\"><div><div class=\"sym\">${a.sym}</div><div class=\"nm\">${esc(a.name)}</div></div><span class=\"badge\">${a.error ? 'FEED ERROR' : 'SCANNING'}</span></div></div>`;\n    const st = a.status === 'NO TRADE' ? 'NO TRADE' : a.status;\n    const tr = ['4h', '1h', '15m'].map(t => `<span class=\"tr ${a.trends[t] === 1 ? 'b' : a.trends[t] === -1 ? 's' : ''}\">${tfL(t)} ${arrow(a.trends[t])}</span>`).join('');\n    return `<div class=\"mc ${a.status === 'NO TRADE' ? '' : a.status}\" data-s=\"${a.sym}\">\n      <div class=\"top\"><div><div class=\"sym\">${a.sym}${a.delay ? `<span class=\"delay\" title=\"Free futures data is delayed\">${a.delay}-min delay</span>` : ''}</div><div class=\"nm\">${esc(a.name)}</div></div><span class=\"badge ${a.status === 'NO TRADE' ? '' : a.status}\">${st}</span></div>\n      <div class=\"px\" data-px=\"${a.sym}\">${fmt(a.price, a.dp)}</div>\n      <div class=\"chg ${a.change24 >= 0 ? 'up' : 'dn'}\" data-chg=\"${a.sym}\">${a.change24 >= 0 ? '+' : ''}${a.change24.toFixed(2)}% · 24h</div>\n      <div class=\"age\" data-age=\"${a.sym}\"><i></i><span>${a.priceSrc || ''}</span></div>\n      <div class=\"trs\">${tr}</div>\n      ${gatesHTML(a.agents)}\n      <div class=\"chk\" style=\"margin-top:10px\">🤖 agents checked <span data-chk=\"${a.sym}\">${secs(Date.now() - clockSkew - a.updatedAt)}</span> ago</div>\n      <div class=\"foot\"><span><b style=\"color:var(--txt)\">${a.passCount}/6</b> agents passed</span><span>${a.dir === 1 ? '<span class=\"up\">Bias BUY</span>' : a.dir === -1 ? '<span class=\"dn\">Bias SELL</span>' : 'No bias'}</span></div>\n    </div>`;\n  }).join('');\n  $('#board').querySelectorAll('.mc').forEach(c => c.onclick = () => choose(c.dataset.s));\n}\n$('#fTabs').onclick = e => { const b = e.target.closest('button'); if (!b) return; filter = b.dataset.f; document.querySelectorAll('#fTabs button').forEach(x => x.classList.toggle('on', x === b)); renderBoard(); };\n\nfunction fillSelect() {\n  const s = $('#symSel'); if (s.options.length === desk.assets.length) return;\n  const g = { crypto: 'Crypto', gold: 'Gold', commodity: 'Commodities', forex: 'Forex' };\n  s.innerHTML = Object.keys(g).map(k => `<optgroup label=\"${g[k]}\">` + desk.assets.filter(a => a.cls === k).map(a => `<option value=\"${a.sym}\">${a.sym}</option>`).join('') + '</optgroup>').join('');\n  if (sel) s.value = sel;\n}\n$('#symSel').onchange = e => choose(e.target.value);\n\nfunction checkNewSignals() {\n  const ids = new Set(desk.signals.map(s => s.id));\n  if (seenSignals && !SNAP) desk.signals.filter(s => !seenSignals.has(s.id)).forEach(s => {\n    toast(`<b>${s.dir} ${s.sym}</b>: all six agents passed<br><span class=\"mono mut\">Entry ${fmt(s.entry, s.dp)} · SL ${fmt(s.sl, s.dp)} · ${s.rr.toFixed(1)}R</span>`, s.dir);\n    beep(s.dir === 'BUY');\n    try { if (window.Notification && Notification.permission === 'granted') new Notification(`SUPER SIX: ${s.dir} ${s.sym}`, { body: `Entry ${fmt(s.entry, s.dp)} SL ${fmt(s.sl, s.dp)}` }); } catch {}\n  });\n  seenSignals = ids;\n}\nfunction toast(html, cls) { const d = document.createElement('div'); d.className = 'toast ' + (cls || ''); d.innerHTML = html; $('#toasts').appendChild(d); setTimeout(() => d.remove(), 9000); }\nfunction beep(up) { try { const c = new (window.AudioContext || window.webkitAudioContext)(); [0, .18].forEach((t, i) => { const o = c.createOscillator(), g = c.createGain(); o.frequency.value = up ? 660 + i * 220 : 660 - i * 220; g.gain.setValueAtTime(.08, c.currentTime + t); g.gain.exponentialRampToValueAtTime(.0001, c.currentTime + t + .16); o.connect(g).connect(c.destination); o.start(c.currentTime + t); o.stop(c.currentTime + t + .17); }); } catch {} }\n\nfunction renderActivity() {\n  const a = desk.activity || [];\n  $('#actSub').textContent = `scan #${desk.scanCount || 0} · last scan ${desk.lastScan ? new Date(desk.lastScan).toLocaleTimeString([], { hour12: false }) : '—'} · ${a.length} recent changes`;\n  if (!a.length) { $('#actList').innerHTML = `<div class=\"empty\" style=\"padding:18px\">No status changes in recent scans. The agents re-check all ${desk.assets.length} markets every 30 seconds and list any change here.</div>`; return; }\n  $('#actList').innerHTML = a.map(x => `<div class=\"ai\" data-s=\"${x.sym}\"><span class=\"tm\">${new Date(x.t).toLocaleTimeString([], { hour12: false })}</span><b>${x.sym}</b><span>${esc(x.text)}</span><span class=\"badge ${['BUY', 'SELL', 'WATCH'].includes(x.status) ? x.status : ''}\">${x.status === 'NO TRADE' ? x.pass + '/6' : x.status}</span></div>`).join('');\n  $('#actList').querySelectorAll('.ai').forEach(r => r.onclick = () => choose(r.dataset.s));\n}\n/* Saved-data notice: calm (no red), but always shows how old the data is */\nfunction checkFrozen() {\n  if (!desk || !desk.lastScan) return;\n  const age = Date.now() - clockSkew - desk.lastScan;\n  const old = age > 120e3;\n  document.body.classList.remove('isfrozen');\n  banner('frozen', null);\n  if (old) banner('saved', `Showing the agents' last scan from ${new Date(desk.lastScan).toLocaleTimeString([], { hour12: false })} (${secs(age)} ago) · ${SNAP ? 'send any message to start a fresh scan' : 'waiting for the next scan'}`, 'saved');\n  else banner('saved', null);\n  if (SNAP && old) {\n    banner('snap', null);\n    $('#arMode').innerHTML = `Showing the last saved scan. The page keeps checking and updates by itself when a newer scan is saved.`;\n  }\n}\nsetInterval(checkFrozen, 5000);\nfunction renderJournal() {\n  const s = desk.signals;\n  $('#jStats').textContent = `${desk.stats.total} signals · ${desk.stats.open} open · ${desk.stats.wins} wins / ${desk.stats.losses} losses`;\n  if (!s.length) { $('#journal').innerHTML = '<div class=\"empty\">No six-agent signals yet.<br>The desk only fires when all six agents pass and the Risk agent approves.<br>Check the <b class=\"gold\">WATCH</b> markets on the Signal Board. They are closest to triggering.</div>'; return; }\n  $('#journal').innerHTML = `<table><tr><th>Time</th><th>Market</th><th>Side</th><th>Entry</th><th>Stop</th><th>Target</th><th>R:R</th><th>Result</th></tr>` +\n    s.map(x => `<tr class=\"clk\" data-s=\"${x.sym}\"><td class=\"mono mut\">${tstr(x.t)}</td><td><b>${x.sym}</b></td><td class=\"${x.dir === 'BUY' ? 'up' : 'dn'}\"><b>${x.dir}</b></td><td class=\"mono\">${fmt(x.entry, x.dp)}</td><td class=\"mono dn\">${fmt(x.sl, x.dp)}</td><td class=\"mono up\">${fmt(x.tp2 ?? x.tp1, x.dp)}</td><td class=\"mono\">${x.rr.toFixed(1)}</td><td><span class=\"oc ${x.outcome.split('/')[0]}\">${x.outcome}${x.tp1Hit && x.outcome === 'OPEN' ? ' · TP1 ✓' : ''}</span></td></tr>`).join('') + '</table>';\n  $('#journal').querySelectorAll('tr.clk').forEach(r => r.onclick = () => choose(r.dataset.s));\n}\nfunction renderCal() {\n  const c = desk.calendar, now = Date.now();\n  if (!c.length) { $('#cal').innerHTML = '<div class=\"empty\">No high or medium-impact events left this week.</div>'; return; }\n  $('#cal').innerHTML = `<table><tr><th>When</th><th>Currency</th><th>Event</th><th>Forecast</th><th></th></tr>` + c.map(e => {\n    const d = e.t - now, soon = d > 0 && d < 3600e3, past = d < 0;\n    return `<tr style=\"${past ? 'opacity:.45' : ''}\"><td class=\"mono mut\">${tstr(e.t)}</td><td><span class=\"imp ${e.impact}\"></span><b>${e.country}</b></td><td style=\"white-space:normal;min-width:180px\">${esc(e.title)}</td><td class=\"mono mut\">${esc(e.forecast)}</td><td class=\"mono ${soon ? 'dn' : 'mut'}\">${past ? 'done' : d < 86400e3 ? 'in ' + (d < 3600e3 ? Math.round(d / 60000) + 'm' : Math.floor(d / 3600e3) + 'h') : ''}</td></tr>`;\n  }).join('') + '</table>';\n}\nfunction renderHeads() {\n  $('#nSrc').textContent = desk.newsSources ? desk.newsSources + ' feeds live' : '';\n  const h = desk.headlines;\n  if (!h.length) { $('#heads').innerHTML = '<div class=\"empty\">Loading headlines…</div>'; return; }\n  $('#heads').innerHTML = h.map(x => `<div class=\"hl\"><a href=\"${esc(x.link)}\" target=\"_blank\" rel=\"noopener\">${esc(x.title)}</a><span class=\"sent ${x.pol > 0 ? 'p' : x.pol < 0 ? 'n' : 'z'}\">${x.pol > 0 ? 'BULLISH' : x.pol < 0 ? 'BEARISH' : 'NEUTRAL'}</span><small>${esc(x.source)} · ${ago(x.t)}${x.ents.length ? ' · ' + x.ents.slice(0, 3).join(', ') : ''}</small></div>`).join('');\n}\n\n/* ── detail ── */\nfunction renderDetail() {\n  const d = detail, dp = d.dp;\n  $('#cPx').innerHTML = `${fmt(d.price, dp)} <span class=\"${d.change24 >= 0 ? 'up' : 'dn'}\" style=\"font-size:14px\">${d.change24 >= 0 ? '+' : ''}${d.change24.toFixed(2)}%</span>`;\n  $('#cName').textContent = d.name + ' · ' + d.cls.toUpperCase() + ' · updated ' + ago(d.updatedAt);\n  $('#agDir').dataset.t = d.updatedAt;\n  $('#agDir').innerHTML = d.dir ? `· bias <b class=\"${d.dir === 1 ? 'up' : 'dn'}\">${d.dir === 1 ? 'BUY ▲' : 'SELL ▼'}</b> · ${d.passCount}/6 passed · checked <span id=\"agAge\">${secs(Date.now() - clockSkew - d.updatedAt)}</span> ago` : `· no bias · checked <span id=\"agAge\">${secs(Date.now() - clockSkew - d.updatedAt)}</span> ago`;\n  const st = d.status, vcls = st === 'NO TRADE' ? 'NO' : st;\n  const sub = st === 'BUY' || st === 'SELL' ? `All six agents passed and the Risk agent approved. Confidence ${d.confidence}/100.`\n    : st === 'WATCH' ? `${d.passCount} of 6 agents passed. The setup is forming, but don't enter yet.`\n    : `${d.passCount} of 6 agents passed. Standing aside: ${d.agents.filter(a => !a.pass).map(a => a.name.replace(' Agent', '')).join(', ')} failed.`;\n  $('#verdict').innerHTML = `<div class=\"verdict ${vcls}\"><div class=\"v\">${st}</div><div>${gatesHTML(d.agents)}<p>${esc(sub)}</p></div></div>`;\n  const p = d.plan;\n  if (p) {\n    const R = x => x == null ? '—' : fmt(x, dp);\n    $('#plan').innerHTML = `<div class=\"plan ${p.provisional ? 'dim' : ''}\">\n      ${p.provisional ? `<div class=\"warn\">⚠ Provisional levels only. The Risk agent has <b>not</b> approved this setup, so do not trade it.</div>` : ''}\n      <div class=\"lv\"><span>Entry · ${p.dir}</span><b>${R(p.entry)}</b></div>\n      <div class=\"lv\"><span>Stop loss</span><b class=\"dn\">${R(p.sl)}</b></div>\n      <div class=\"lv\"><span>TP1 · ${esc(p.tp1Label)}</span><b class=\"up\">${R(p.tp1)}</b></div>\n      <div class=\"lv\"><span>TP2 · ${esc(p.tp2Label || 'n/a')}</span><b class=\"up\">${R(p.tp2)}</b></div>\n      <div class=\"lv\"><span>Reward : risk</span><b>${p.rr ? p.rr.toFixed(2) + 'R' : '—'}</b></div>\n      <div class=\"lv\"><span>Risk amount</span><b>$${fmt(p.riskCash, 0)}</b></div>\n      <div class=\"lv\"><span>Size · ${esc(p.lotUnit)}</span><b>${p.lots != null ? fmt(p.lots, 2) : fmt(p.units, p.units < 10 ? 4 : 2)}</b></div>\n    </div>`;\n  } else $('#plan').innerHTML = `<div class=\"plan dim\"><div class=\"warn\" style=\"color:var(--mut);background:var(--card);border-color:var(--line)\">No protective structure at the current price, so the Risk agent cannot build a trade plan.</div></div>`;\n  $('#agents').innerHTML = d.agents.map((a, i) => {\n    const col = a.score >= 75 ? 'var(--buy)' : a.score >= 50 ? 'var(--gold)' : 'var(--sell)';\n    const checks = a.checks.map(c => `<div class=\"ck\"><span class=\"ic ${c.ok ? 'ok' : c.req ? 'no' : 'opt'}\">${c.ok ? '✓' : c.req ? '✗' : '·'}</span><div class=\"lb\"><span>${esc(c.label)}</span><em>${c.req ? 'REQUIRED' : 'BONUS'}</em></div><div class=\"dt\">${esc(c.detail)}</div></div>`).join('');\n    const heads = a.headlines && a.headlines.length ? `<div class=\"heads\">${a.headlines.slice(0, 3).map(h => `<a href=\"${esc(h.link)}\" target=\"_blank\" rel=\"noopener\"><span class=\"${h.pol > 0 ? 'up' : h.pol < 0 ? 'dn' : 'mut'}\">●</span> ${esc(h.title)} <span class=\"mut\">· ${ago(h.t)}</span></a>`).join('')}</div>` : '';\n    return `<div class=\"ag ${a.pass ? 'pass' : 'fail'} ${a.veto ? 'veto' : ''}\">\n      <div class=\"hd\"><div class=\"num\">${i + 1}</div><div class=\"t\"><b>${esc(a.name)}</b><span>${esc(a.tag)}</span></div>${a.veto ? '<span class=\"vtag\">VETO</span>' : ''}<span class=\"pill ${a.status}\">${a.status}</span></div>\n      <div class=\"sbar\"><i style=\"width:${a.score}%;background:${col}\"></i></div>\n      <div class=\"sum\">${esc(a.summary)} <span class=\"mono mut\">· ${a.score}/100</span></div>\n      ${checks}${heads}\n    </div>`;\n  }).join('');\n}\n\n/* ── chart ── */\nconst cv = $('#chart'), ctx = cv.getContext('2d');\nconst PR = 84, PB = 26;\nconst MONO = getComputedStyle(document.documentElement).getPropertyValue('--mono');\nfunction niceStep(range, n) { const raw = range / n, p = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / p; return (f < 1.5 ? 1 : f < 3 ? 2 : f < 7 ? 5 : 10) * p; }\nfunction drawChart() {\n  if (!detail || viewName !== 'analysis') return;\n  const ch = detail.charts[tf]; if (!ch) return;\n  $('#chartMsg').style.display = 'none';\n  const C = ch.candles, n = C.length, dp = detail.dp;\n  const rect = cv.getBoundingClientRect(); if (!rect.width) return;\n  const dpr = window.devicePixelRatio || 1;\n  if (cv.width !== Math.round(rect.width * dpr) || cv.height !== Math.round(rect.height * dpr)) { cv.width = Math.round(rect.width * dpr); cv.height = Math.round(rect.height * dpr); }\n  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  const w = rect.width, h = rect.height, W = w - PR, H = h - PB;\n  if (rect.width < 700 && view.end == null) view.count = 70;\n  if (view.end == null) view.end = n + 8;\n  view.count = Math.max(25, Math.min(n + 40, view.count));\n  view.end = Math.max(25, Math.min(n + 60, view.end));\n  const start = view.end - view.count, bw = W / view.count;\n  const X = i => (i - start + 0.5) * bw;\n  const i0 = Math.max(0, Math.floor(start)), i1 = Math.min(n - 1, Math.ceil(view.end));\n  let lo = Infinity, hi = -Infinity;\n  for (let i = i0; i <= i1; i++) { lo = Math.min(lo, C[i][3]); hi = Math.max(hi, C[i][2]); }\n  const p = detail.plan;\n  if (p && ov.plan) { const span = hi - lo; [p.sl, p.tp1, p.tp2].forEach(v => { if (v != null && v > lo - span * .6 && v < hi + span * .6) { lo = Math.min(lo, v); hi = Math.max(hi, v); } }); }\n  const pad = (hi - lo) * .08 || 1; lo -= pad; hi += pad;\n  const Y = v => H - (v - lo) / (hi - lo) * H, PV = y => lo + (H - y) / H * (hi - lo);\n  const vis = (a, b) => !(Y(a) > H && Y(b) > H) && !(Y(a) < 0 && Y(b) < 0);\n\n  ctx.clearRect(0, 0, w, h); ctx.fillStyle = '#0b0f16'; ctx.fillRect(0, 0, w, h);\n  ctx.font = '11px ' + MONO;\n  const step = niceStep(hi - lo, Math.max(4, Math.floor(H / 70)));\n  ctx.strokeStyle = '#141b27'; ctx.lineWidth = 1; ctx.fillStyle = '#6b7588'; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';\n  for (let v = Math.ceil(lo / step) * step; v < hi; v += step) { const y = Math.round(Y(v)) + .5; ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke(); ctx.fillText(fmt(v, dp), W + 8, y); }\n  const tStep = Math.max(1, Math.round(120 / bw));\n  ctx.textAlign = 'center'; ctx.textBaseline = 'top';\n  for (let i = i0 - (i0 % tStep); i <= i1; i += tStep) {\n    if (i < 0) continue; const x = Math.round(X(i)) + .5;\n    ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke();\n    const d = new Date(C[i][0]);\n    ctx.fillText(tf === '4h' ? d.toLocaleDateString([], { month: 'short', day: '2-digit' }) : d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }), x, H + 7);\n  }\n  ctx.save(); ctx.beginPath(); ctx.rect(0, 0, W, H); ctx.clip();\n  const placed = [];\n  function label(x, y, txt, col, align) {\n    ctx.font = '600 10.5px sans-serif';\n    const tw = ctx.measureText(txt).width, lx = align === 'right' ? x - tw : x;\n    if (placed.some(r => Math.abs(r.y - y) < 12 && lx < r.x2 && lx + tw > r.x1)) return;\n    placed.push({ x1: lx, x2: lx + tw, y });\n    ctx.fillStyle = 'rgba(11,15,22,.75)'; ctx.fillRect(lx - 3, y - 7, tw + 6, 14);\n    ctx.fillStyle = col; ctx.textAlign = 'left'; ctx.textBaseline = 'middle'; ctx.fillText(txt, lx, y);\n  }\n  function hline(x1, x2, v, col, dash) { const y = Math.round(Y(v)) + .5; ctx.strokeStyle = col; ctx.lineWidth = 1; ctx.setLineDash(dash || []); ctx.beginPath(); ctx.moveTo(x1, y); ctx.lineTo(x2, y); ctx.stroke(); ctx.setLineDash([]); }\n\n  if (ov.pd && ch.dr) {\n    const xs = Math.max(0, X(ch.dr.from) - bw / 2);\n    ctx.fillStyle = 'rgba(242,70,93,.05)'; ctx.fillRect(xs, Y(ch.dr.hi), W - xs, Y(ch.dr.eq) - Y(ch.dr.hi));\n    ctx.fillStyle = 'rgba(25,201,138,.05)'; ctx.fillRect(xs, Y(ch.dr.eq), W - xs, Y(ch.dr.lo) - Y(ch.dr.eq));\n    hline(xs, W, ch.dr.eq, 'rgba(245,197,66,.7)', [6, 4]); label(xs + 6, Y(ch.dr.eq) - 9, 'EQUILIBRIUM', '#f5c542');\n  }\n  for (const z of ch.fvg) {\n    const inv = z.kind === 'iFVG'; if (inv ? !ov.ifvg : !ov.fvg) continue; if (!vis(z.top, z.bottom)) continue;\n    const x1 = Math.max(0, X(z.i) - bw / 2), y1 = Y(z.top), y2 = Y(z.bottom); if (x1 > W) continue;\n    if (inv) { ctx.fillStyle = 'rgba(167,139,250,.12)'; ctx.fillRect(x1, y1, W - x1, y2 - y1); ctx.setLineDash([4, 3]); ctx.strokeStyle = 'rgba(167,139,250,.6)'; ctx.strokeRect(x1, y1, W - x1, y2 - y1); ctx.setLineDash([]); }\n    else { ctx.fillStyle = z.dir === 1 ? 'rgba(25,201,138,.10)' : 'rgba(242,70,93,.10)'; ctx.fillRect(x1, y1, W - x1, y2 - y1); }\n    if (y2 - y1 > 10) label(x1 + 5, (y1 + y2) / 2, inv ? (z.eff === 1 ? 'iFVG ▲' : 'iFVG ▼') : (z.dir === 1 ? 'FVG ▲' : 'FVG ▼'), inv ? '#c4b5fd' : z.dir === 1 ? '#19c98a' : '#f2465d');\n  }\n  if (ov.ob) for (const z of ch.ob) {\n    if (!vis(z.top, z.bottom)) continue;\n    const x1 = Math.max(0, X(z.i) - bw / 2), y1 = Y(z.top), y2 = Y(z.bottom), col = z.dir === 1 ? '75,147,255' : '255,159,28';\n    ctx.fillStyle = `rgba(${col},${z.state === 'fresh' ? .18 : .09})`; ctx.fillRect(x1, y1, W - x1, y2 - y1);\n    ctx.strokeStyle = `rgba(${col},.7)`; ctx.strokeRect(x1 + .5, y1 + .5, W - x1, y2 - y1);\n    label(x1 + 5, y1 + 8, z.dir === 1 ? 'Bullish OB' : 'Bearish OB', `rgb(${col})`);\n  }\n  if (ov.liq) {\n    for (const l of ch.liq.bsl) { hline(X(l.i), W, l.price, 'rgba(34,211,238,.55)', [2, 3]); label(W - 6, Y(l.price) - 8, l.count > 1 ? `EQH ×${l.count}` : 'BSL', '#22d3ee', 'right'); }\n    for (const l of ch.liq.ssl) { hline(X(l.i), W, l.price, 'rgba(34,211,238,.55)', [2, 3]); label(W - 6, Y(l.price) + 8, l.count > 1 ? `EQL ×${l.count}` : 'SSL', '#22d3ee', 'right'); }\n    for (const s of ch.liq.sweeps) {\n      hline(X(s.from), X(s.at), s.price, 'rgba(245,197,66,.5)', [1, 2]);\n      const x = X(s.at), y = Y(s.wick) + (s.side === 'SSL' ? 12 : -12);\n      ctx.fillStyle = '#f5c542'; ctx.font = 'bold 12px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText(s.side === 'SSL' ? '▲' : '▼', x, y);\n    }\n  }\n  if (ov.bos) for (const e of ch.ev) {\n    const x1 = X(e.from), x2 = X(e.i), col = e.dir === 1 ? '#19c98a' : '#f2465d';\n    hline(x1, x2, e.level, col, e.type === 'CHoCH' ? [5, 3] : []);\n    ctx.fillStyle = col; ctx.font = 'bold 10px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = e.dir === 1 ? 'bottom' : 'top';\n    ctx.fillText(e.type, (x1 + x2) / 2, Y(e.level) + (e.dir === 1 ? -3 : 3));\n  }\n  const cw = Math.max(1, bw * .66);\n  for (let i = i0; i <= i1; i++) {\n    const [, o, hh, ll, c, closed] = C[i], x = X(i), up = c >= o;\n    ctx.globalAlpha = closed ? 1 : .7; ctx.strokeStyle = ctx.fillStyle = up ? '#19c98a' : '#f2465d';\n    ctx.beginPath(); ctx.moveTo(Math.round(x) + .5, Y(hh)); ctx.lineTo(Math.round(x) + .5, Y(ll)); ctx.stroke();\n    ctx.fillRect(x - cw / 2, Y(Math.max(o, c)), cw, Math.max(1, Math.abs(Y(o) - Y(c))));\n  }\n  ctx.globalAlpha = 1;\n  const tags = [];\n  if (p && ov.plan) {\n    const xs = Math.max(0, X(n - 1) - bw * 10), dash = p.provisional ? [6, 4] : [];\n    if (p.tp2 != null) { ctx.fillStyle = 'rgba(25,201,138,.07)'; ctx.fillRect(xs, Math.min(Y(p.entry), Y(p.tp2)), W - xs, Math.abs(Y(p.tp2) - Y(p.entry))); }\n    ctx.fillStyle = 'rgba(242,70,93,.08)'; ctx.fillRect(xs, Math.min(Y(p.entry), Y(p.sl)), W - xs, Math.abs(Y(p.sl) - Y(p.entry)));\n    [[p.sl, '#f2465d', 'SL'], [p.tp1, '#7ee2b8', 'TP1'], [p.tp2, '#19c98a', 'TP2'], [p.entry, '#e9edf3', (p.provisional ? 'Provisional ' : '') + p.dir]].forEach(([v, col, t]) => { if (v == null) return; hline(xs, W, v, col, dash); label(xs + 4, Y(v) - 9, t, col); tags.push([v, col]); });\n  }\n  const last = C[n - 1][4], lastUp = C[n - 1][4] >= C[n - 1][1];\n  hline(0, W, last, lastUp ? 'rgba(25,201,138,.55)' : 'rgba(242,70,93,.55)', [1, 2]);\n  ctx.restore();\n  const axisTag = (y, txt, bg, fg) => { if (y < -8 || y > H + 8) return; ctx.font = '11px ' + MONO; ctx.fillStyle = bg; ctx.fillRect(W + 1, y - 9, PR - 2, 18); ctx.fillStyle = fg; ctx.textAlign = 'left'; ctx.textBaseline = 'middle'; ctx.fillText(txt, W + 7, y); };\n  tags.forEach(([v, col]) => axisTag(Y(v), fmt(v, dp), col, '#0b0f16'));\n  axisTag(Y(last), fmt(last, dp), lastUp ? '#19c98a' : '#f2465d', '#fff');\n  let hov = n - 1;\n  if (mouse && mouse.x < W && mouse.y < H) {\n    ctx.strokeStyle = 'rgba(200,210,225,.35)'; ctx.setLineDash([3, 3]); ctx.beginPath(); ctx.moveTo(0, mouse.y + .5); ctx.lineTo(W, mouse.y + .5); ctx.moveTo(mouse.x + .5, 0); ctx.lineTo(mouse.x + .5, H); ctx.stroke(); ctx.setLineDash([]);\n    axisTag(mouse.y, fmt(PV(mouse.y), dp), '#2b3546', '#fff');\n    hov = Math.max(0, Math.min(n - 1, Math.floor(start + mouse.x / bw)));\n  }\n  const k = C[hov], cu = k[4] >= k[1] ? 'up' : 'dn';\n  $('#ohlc').innerHTML = `<b style=\"color:var(--txt)\">${detail.sym}</b> · ${tfL(tf)} · ${tstr(k[0])} &nbsp;&nbsp; O <span class=\"${cu}\">${fmt(k[1], dp)}</span> &nbsp;H <span class=\"${cu}\">${fmt(k[2], dp)}</span> &nbsp;L <span class=\"${cu}\">${fmt(k[3], dp)}</span> &nbsp;C <span class=\"${cu}\">${fmt(k[4], dp)}</span> &nbsp;&nbsp; ATR ${fmt(ch.atr, dp)} &nbsp;&nbsp; Trend <b class=\"${ch.trend === 1 ? 'up' : ch.trend === -1 ? 'dn' : ''}\">${ch.trend === 1 ? 'BULLISH' : ch.trend === -1 ? 'BEARISH' : 'RANGE'}</b>`;\n}\nlet drag = null;\nconst pos = e => { const r = cv.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top, w: r.width }; };\ncv.addEventListener('pointermove', e => { const q = pos(e); mouse = q; if (drag) view.end = drag.end - (e.clientX - drag.x) / ((q.w - PR) / view.count); drawChart(); });\ncv.addEventListener('pointerleave', () => { mouse = null; drag = null; drawChart(); });\ncv.addEventListener('pointerdown', e => { drag = { x: e.clientX, end: view.end }; cv.setPointerCapture(e.pointerId); });\ncv.addEventListener('pointerup', () => { drag = null; });\ncv.addEventListener('dblclick', () => { view = { end: null, count: 100 }; drawChart(); });\ncv.addEventListener('wheel', e => {\n  e.preventDefault(); if (!detail) return;\n  const q = pos(e), W = q.w - PR, fx = Math.min(1, q.x / W), anchor = view.end - view.count + fx * view.count;\n  const nc = Math.max(25, Math.min(detail.charts[tf].candles.length + 40, view.count * (e.deltaY > 0 ? 1.12 : 0.89)));\n  view.end = anchor + (1 - fx) * nc; view.count = nc; drawChart();\n}, { passive: false });\nnew ResizeObserver(() => drawChart()).observe($('#chartWrap'));\n\n$('#tfTabs').onclick = e => { const b = e.target.closest('button'); if (!b) return; tf = b.dataset.tf; document.querySelectorAll('#tfTabs button').forEach(x => x.classList.toggle('on', x === b)); view = { end: null, count: 100 }; drawChart(); renderTV(); };\n$('#ovTg').onclick = e => { const b = e.target.closest('button'); if (!b) return; ov[b.dataset.o] = ov[b.dataset.o] ? 0 : 1; b.classList.toggle('on', !!ov[b.dataset.o]); drawChart(); };\n$('#bScan').onclick = async () => { $('#bScan').textContent = '⟳ Scanning…'; try { await api('api/scan', { method: 'POST' }); } catch {} $('#bScan').textContent = '⟳ Scan now'; loadDesk(); loadDetail(); };\n$('#bSet').onclick = () => { const s = desk ? desk.settings : {}; $('#sAcc').value = s.account; $('#sRisk').value = s.riskPct; $('#sRR').value = s.minRR; $('#sConf').value = s.minConf; $('#mSet').classList.add('on'); try { if (window.Notification && Notification.permission === 'default') Notification.requestPermission(); } catch {} };\n$('#sCancel').onclick = () => $('#mSet').classList.remove('on');\n$('#sSave').onclick = async () => {\n  try { await api('api/settings', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ account: $('#sAcc').value, riskPct: $('#sRisk').value, minRR: $('#sRR').value, minConf: $('#sConf').value }) }); toast('Risk settings saved. Rescanning all markets…'); } catch { toast('Could not save settings.'); }\n  $('#mSet').classList.remove('on'); setTimeout(() => { loadDesk(); loadDetail(); }, 2500);\n};\n\nfunction secs(ms) { const s = Math.max(0, Math.round(ms / 1000)); return s < 60 ? s + 's' : Math.floor(s / 60) + 'm ' + (s % 60) + 's'; }\nfunction tickRefresh() {\n  if (SNAP) return;\n  const now = Date.now();\n  const row = (id, last, every) => {\n    if (!last) return;\n    const el = now - last, left = Math.max(0, every - el);\n    $(id + 's').textContent = `last ${secs(el)} ago · next in ${secs(left)}`;\n    $(id + 'b').style.width = Math.min(100, el / every * 100) + '%';\n  };\n  if (desk && desk.lastScan) row('#r1', desk.lastScan, 30000);\n  row('#r0', lastPriceFetch, 2000);\n  if (lastPriceFetch) $('#r0s').textContent = `last tick ${secs(now - lastPriceFetch)} ago · ${Object.keys(livePrices).length} markets streaming`;\n  updateAges();\n  row('#r2', lastDeskFetch, 15000);\n  row('#r3', lastDetailFetch, 20000);\n  $('#arTxt').textContent = lastDeskFetch ? secs(now - lastDeskFetch) + ' ago' : 'ON';\n}\nsetInterval(tickRefresh, 1000);\nsetInterval(() => {\n  $('#hClock').textContent = new Date().toLocaleTimeString([], { hour12: false });\n  if (SNAP) return;\n  if (desk && desk.lastScan) { const s = Math.max(0, Math.round((desk.lastScan + 30000 - Date.now()) / 1000)); $('#hNext').textContent = desk.scanning ? 'scanning' : s + 's'; }\n}, 1000);\ntry { $('#hTz').textContent = Intl.DateTimeFormat().resolvedOptions().timeZone.split('/').pop().replace('_', ' '); } catch {}\n\n/* ── snapshot mode (file viewer): NEVER navigates/reloads — updates in place so the page can't go blank ── */\nconst RELOAD_MS = 30000;\nlet snapTries = 0, snapFails = 0, snapNew = 0, snapNext = Date.now() + RELOAD_MS;\nfunction snapUI() {\n  const savedAt = new Date(SNAP.desk.lastScan).toLocaleTimeString([], { hour12: false });\n  const age = Date.now() - SNAP.desk.lastScan, stale = age > 120000;\n  $('#arMode').innerHTML = stale\n    ? `Showing the scan saved at ${savedAt}. Send any message to start a fresh scan, or run the desk on your own computer for nonstop scanning.`\n    : `<b class=\"up\">ON:</b> showing the scan saved at ${savedAt}. The page checks for a newer save every 30 seconds and updates in place.${snapNew ? ' <b class=\"up\">✓ New data loaded.</b>' : ''}`;\n  banner('snap', stale ? null : `Saved scan ${savedAt} · checks for newer data every 30 seconds`);\n}\nasync function snapRefresh() {\n  snapTries++; snapNext = Date.now() + RELOAD_MS;\n  try {\n    const r = await fetch(location.href, { cache: 'no-store' });\n    const t = await r.text();\n    const i = t.indexOf('window.__SNAPSHOT__='), j = t.indexOf(';<' + '/script>', i);\n    if (i < 0 || j < 0) throw new Error('no data');\n    const n = JSON.parse(t.slice(i + 20, j));\n    if (n && n.desk && n.desk.lastScan > SNAP.desk.lastScan) {\n      SNAP.desk = n.desk; SNAP.assets = n.assets; snapNew++;\n      await loadDesk(); if (sel) await loadDetail();\n      toast('⟳ New scan loaded: ' + new Date(n.desk.lastScan).toLocaleTimeString([], { hour12: false }));\n    }\n  } catch { snapFails++; }\n  snapUI();\n}\nif (SNAP) {\n  $('#liveDot').classList.add('snap'); $('#modeTxt').textContent = 'Saved view';\n  $('#bScan').textContent = '⟳ Check for new data'; $('#bScan').onclick = () => snapRefresh();\n  $('#bSet').style.display = 'none';\n  $('#r2').textContent = 'check every 30s'; $('#r0').textContent = 'saved with each scan'; $('#r0s').textContent = 'prices as of the last save'; $('#r3').textContent = 'with each save';\n  $('#r3s').textContent = 'chart & agents included in each save';\n  const t0 = Date.now();\n  setInterval(() => {\n    const left = Math.max(0, snapNext - Date.now());\n    const savedAt = new Date(SNAP.desk.lastScan).toLocaleTimeString([], { hour12: false });\n    const age = Date.now() - SNAP.desk.lastScan;\n    $('#r1s').textContent = `last saved scan ${savedAt} (${secs(age)} ago)`;\n    $('#r1b').style.width = Math.min(100, age / 30000 * 100) + '%'; updateAges();\n    $('#r2s').textContent = `next check in ${secs(left)}`;\n    $('#r2b').style.width = Math.min(100, (RELOAD_MS - left) / RELOAD_MS * 100) + '%';\n    $('#arTxt').textContent = 'check in ' + secs(left);\n    $('#hNext').textContent = secs(left);\n  }, 1000);\n  setInterval(snapRefresh, RELOAD_MS);\n  snapUI();\n}\nsetMode(tvMode);\nloadDesk();\nsetInterval(loadDesk, 15000);\nsetInterval(pollPrices, 2000);\nsetInterval(loadDetail, 20000);\n</script>\n</body>\n</html>\n"};
const dir = path.join(__dirname, 'app');
